                    <div key={bz.code} className="px-3 py-1 flex flex-wrap items-center gap-2 text-sm">
                      <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bz.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
                        {bz.code}
                      </span>
