    12→  perRepeater: { short_name: string; count: number }[];
    13→}
    14→
    15→export default function ExercisePage() {
    16→  const { id } = useParams<{ id: string }>();
    17→  const [exercise, setExercise] = useState<any>(null);
    18→  const [mode, setMode] = useState<'land' | 'bund'>('land');
    19→  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
    20→  const [reports, setReports] = useState<any[]>([]);
    21→  const [loading, setLoading] = useState(true);
    22→  const socketRef = useRef(getSocket());
    23→
    24→  const refreshStats = useCallback(async () => {
    25→    if (!id) return;
    26→    try {
    27→      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
    28→      setStats(s);
    29→    } catch {}
    30→  }, [id]);
    31→
    32→  useEffect(() => {
    33→    if (!id) return;
    34→    setLoading(true);
    35→    apiFetch(`/api/v1/exercises/${id}`)
    36→      .then(data => {
    37→        setExercise(data);
    38→        setReports(data.reports || []);
    39→      })
    40→      .catch(() => {})
    41→      .finally(() => setLoading(false));
    42→    refreshStats();
    43→  }, [id, refreshStats]);
    44→
    45→  useEffect(() => {
    46→    if (!id) return;
    47→    const socket = socketRef.current;
    48→    socket.emit('join_exercise', { exercise_id: parseInt(id) });
    49→
    50→    socket.on('report_created', (data: any) => {
    51→      setReports(prev => [data, ...prev]);
    52→      refreshStats();
    53→    });
    54→    socket.on('report_updated', (data: any) => {
    55→      setReports(prev => prev.map(r => r.id === data.id ? data : r));
    56→      refreshStats();
    57→    });
    58→    socket.on('report_deleted', (data: any) => {
    59→      setReports(prev => prev.filter(r => r.id !== data.report_id));
    60→      refreshStats();
    61→    });
    62→
    63→    return () => {
    64→      socket.emit('leave_exercise', { exercise_id: parseInt(id) });
    65→      socket.off('report_created');
    66→      socket.off('report_updated');
    67→      socket.off('report_deleted');
    68→    };
    69→  }, [id, refreshStats]);
    70→
    71→  const handleReportCreated = useCallback((report: any) => {
    72→    setReports(prev => [report, ...prev]);
    73→    socketRef.current.emit('report_created', { ...report, exercise_id: parseInt(id!) });
    74→    refreshStats();
    75→  }, [id, refreshStats]);
    76→
    77→  const handleReportUpdated = useCallback((report: any) => {
    78→    setReports(prev => prev.map(r => r.id === report.id ? report : r));
    79→    socketRef.current.emit('report_updated', { ...report, exercise_id: parseInt(id!) });
    80→    refreshStats();
    81→  }, [id, refreshStats]);
    82→
    83→  const handleReportDeleted = useCallback((reportId: number) => {
    84→    setReports(prev => prev.filter(r => r.id !== reportId));
    85→    socketRef.current.emit('report_deleted', { report_id: reportId, exercise_id: parseInt(id!) });
    86→    refreshStats();
    87→  }, [id, refreshStats]);
    88→
    89→  if (loading) return <p className="text-gray-500 p-4">Laden...</p>;
    90→  if (!exercise) return <p className="text-red-500 p-4">Übung nicht gefunden</p>;
    91→
    92→  return (
    93→    <div className="space-y-4">
    94→      <div className="flex items-center justify-between flex-wrap gap-2">
    95→        <h1 className="text-xl font-bold text-[#5b3a1a]">
    96→          {exercise.name || 'Übung'} — {new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' })}
    97→        </h1>
    98→        <div className="flex items-center gap-2">
    99→          <Link to={`/exercises/${id}/setup`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-1 rounded text-sm">
   100→            Einrichten
   101→          </Link>
   102→          <Link to={`/exercises/${id}/reports`} className="bg-amber-100 hover:bg-amber-200 text-amber-800 px-3 py-1 rounded text-sm">
   103→            Auswertung
   104→          </Link>
   105→        </div>
   106→      </div>
   107→
   108→      <RunningTotals stats={stats} />
   109→
   110→      <div className="flex gap-1 bg-white rounded-lg p-1 shadow-sm w-fit">
   111→        <button
   112→          onClick={() => setMode('land')}
   113→          className={`px-4 py-1.5 rounded text-sm font-medium ${mode === 'land' ? 'bg-[#5b3a1a] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
   114→        >
   115→          Land (Umsetzer)
   116→        </button>
   117→        <button
   118→          onClick={() => setMode('bund')}
   119→          className={`px-4 py-1.5 rounded text-sm font-medium ${mode === 'bund' ? 'bg-[#5b3a1a] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
   120→        >
   121→          Bund (Bundesland)
   122→        </button>
   123→      </div>
   124→
   125→      {mode === 'land' ? (
   126→        <LandMode
   127→          exerciseId={parseInt(id!)}
   128→          repeaters={exercise.repeaters || []}
   129→          reports={reports}
   130→          onReportCreated={handleReportCreated}
   131→          onReportUpdated={handleReportUpdated}
   132→          onReportDeleted={handleReportDeleted}
   133→        />
   134→      ) : (
   135→        <BundMode
   136→          exerciseId={parseInt(id!)}
   137→          repeaters={exercise.repeaters || []}
   138→          reports={reports}
   139→          onReportCreated={handleReportCreated}
   140→          onReportUpdated={handleReportUpdated}
   141→          onReportDeleted={handleReportDeleted}
   142→        />
   143→      )}
   144→    </div>
   145→  );
   146→}
