   356→          const blBezirke = allBezirke.filter(b => b.bundesland_code === bl.code);
   357→          const blReports = repeaterReports.filter(r => r.bundesland_code === bl.code);
   358→          if (blReports.length === 0) return null;
   359→
   360→          return (
   361→            <div key={bl.code} className="bg-white rounded-lg shadow-sm overflow-hidden">
   362→              <div className="bg-gray-50 px-3 py-1.5 flex items-center gap-2 border-b">
   363→                <span className="font-medium text-sm">{bl.name}</span>
   364→                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full">{blReports.filter(r => !r.is_op_marker && r.readability).length}</span>
   365→              </div>
   366→              <div className="divide-y divide-gray-100">
   367→                {blBezirke.map(bz => {
   368→                  const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
   369→                  if (bzReports.length === 0) return null;
   370→                  return (
   371→                    <div key={bz.code} className="px-3 py-1 flex flex-wrap items-center gap-2 text-sm">
   372→                      <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bz.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   373→                        {bz.code}
   374→                      </span>
   375→                      <div className="flex flex-wrap gap-2 flex-1">
   376→                        {bzReports.map(r => (
   377→                          <span
   378→                            key={r.id}
   379→                            onClick={() => handleEdit(r)}
   380→                            className="cursor-pointer hover:bg-amber-50 px-1 rounded group"
   381→                          >
   382→                            <span className="font-mono text-xs">{r.callsign}</span>
   383→                            {r.readability && r.strength && (
   384→                              <span className="ml-1 text-gray-500 text-xs">
   385→                                {r.readability}/{r.strength}{r.db_over_s9 || ''}
   386→                              </span>
   387→                            )}
   388→                            {r.notes && <span className="ml-1 text-amber-600 text-xs">({r.notes})</span>}
   389→                            <button
   390→                              onClick={e => { e.stopPropagation(); handleDelete(r.id); }}
   391→                              className="ml-1 text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 text-xs"
   392→                            >
   393→                              x
   394→                            </button>
   395→                          </span>
   396→                        ))}
   397→                      </div>
   398→                    </div>
   399→                  );
   400→                })}
   401→              </div>
   402→            </div>
   403→          );
   404→        })}
   405→
   406→        {/* Uncategorized */}
   407→        {reportsByBezirk['_other']?.length > 0 && (
   408→          <div className="bg-white rounded-lg shadow-sm p-3">
   409→            <div className="text-sm font-medium mb-1">Sonstige</div>
   410→            {reportsByBezirk['_other'].map(r => (
