          <select
            value={form.einstiegspunktId || defaultEpId || ''}
            onChange={e => setForm(f => ({ ...f, einstiegspunktId: e.target.value ? parseInt(e.target.value) : null }))}
            className="text-xs border border-gray-300 rounded px-1 py-0.5"
