    19→
    20→export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    21→  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
    22→  const [bezirke, setBezirke] = useState<any[]>([]);
    23→  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
    24→  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
    25→  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
    26→  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
    27→  const [editingId, setEditingId] = useState<number | null>(null);
    28→  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
    29→
    30→  useEffect(() => {
    31→    Promise.all([
    32→      apiFetch('/api/v1/reference/bundeslaender'),
    33→      apiFetch('/api/v1/reference/bezirke'),
    34→      apiFetch('/api/v1/repeaters'),
    35→      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    36→    ]).then(([bl, bz, allReps, exReps]) => {
    37→      setBundeslaender(bl);
    38→      setBezirke(bz);
    39→      const linked = allReps.filter((r: any) => r.is_linked);
    40→      setLinkedRepeaters(linked);
    41→      // Initialize per-BL defaults: first linked in that BL, else first overall
    42→      const defaults: Record<string, number> = {};
    43→      const ops: Record<string, string> = {};
    44→      for (const b of bl) {
    45→        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
    46→        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
    47→        defaults[b.code] = repId;
    48→        // Load existing OP callsign from exercise_repeaters
    49→        const exRep = exReps.find((er: any) => er.repeater_id === repId);
    50→        ops[b.code] = exRep?.operator_callsign || '';
    51→      }
    52→      setBlRepSelection(defaults);
    53→      setBlOpCallsigns(ops);
    54→    }).catch(() => {});
    55→  }, [exerciseId]);
    56→
    57→  const saveOpCallsign = async (blCode: string, val: string) => {
    58→    const repId = blRepSelection[blCode];
    59→    if (!repId) return;
    60→    try {
    61→      // Ensure exercise_repeater exists, then update
    62→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
    63→        method: 'POST',
    64→        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
    65→      });
    66→    } catch {
    67→      // Already exists, just patch
    68→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
    69→        method: 'PATCH',
    70→        body: JSON.stringify({ operator_callsign: val || null }),
    71→      });
    72→    }
    73→  };
    74→
    75→  const toggleBl = (code: string) => {
    76→    setCollapsedBl(prev => {
    77→      const next = new Set(prev);
    78→      if (next.has(code)) next.delete(code); else next.add(code);
    79→      return next;
    80→    });
    81→  };
    82→
    83→  const parseRapport = (raw: string) => {
    84→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    85→    if (!match) return { readability: null, strength: null, db_over_s9: null };
    86→    return {
