     1→import { useState, useEffect, type FormEvent } from 'react';
     2→import { apiFetch, getOrCreateOperator } from '../services/api';
     3→import CallsignInput from './CallsignInput';
     4→
     5→const BUNDESLAND_NAMES: Record<string, string> = {
     6→  '01': 'OE1 Wien',
     7→  '02': 'OE2 Salzburg',
     8→  '03': 'OE3 Niederösterreich',
     9→  '04': 'OE4 Burgenland',
    10→  '05': 'OE5 Oberösterreich',
    11→  '06': 'OE6 Steiermark',
    12→  '07': 'OE7 Tirol',
    13→  '08': 'OE8 Kärnten',
    14→  '09': 'OE9 Vorarlberg',
    15→  '10': 'Slowenien',
    16→};
    17→
    18→interface Props {
    19→  exerciseId: string;
    20→  repeaters: any[];
    21→  reports: any[];
    22→  onReportCreated: (report: any) => void;
    23→  onReportUpdated: (report: any) => void;
    24→  onReportDeleted: (reportId: number) => void;
    25→}
    26→
    27→export default function LandMode({ exerciseId, repeaters, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    28→  const [activeRepeaterId, setActiveRepeaterId] = useState<number | null>(null);
    29→  const [allBezirke, setAllBezirke] = useState<any[]>([]);
    30→  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
    31→
    32→  // Entry form state
    33→  const [callsign, setCallsign] = useState('');
    34→  const [selectedOperator, setSelectedOperator] = useState<any>(null);
    35→  const [rapport, setRapport] = useState('');
    36→  const [notes, setNotes] = useState('');
    37→  const [editingId, setEditingId] = useState<number | null>(null);
    38→
    39→  useEffect(() => {
    40→    apiFetch('/api/v1/reference/bundeslaender').then(setBundeslaender).catch(() => {});
    41→    apiFetch('/api/v1/reference/bezirke').then(setAllBezirke).catch(() => {});
    42→  }, []);
    43→
    44→  useEffect(() => {
    45→    if (repeaters.length > 0 && !activeRepeaterId) {
    46→      setActiveRepeaterId(repeaters[0].repeater_id);
    47→    }
    48→  }, [repeaters, activeRepeaterId]);
    49→
    50→  const activeRepeater = repeaters.find(r => r.repeater_id === activeRepeaterId);
    51→  const repeaterReports = reports.filter(r => r.repeater_id === activeRepeaterId);
    52→
    53→  // Group repeaters by Bundesland
    54→  const repeatersByBl: Record<string, any[]> = {};
    55→  const simplexRepeaters: any[] = [];
    56→  const linkedRepeaters: any[] = [];
    57→  for (const r of repeaters) {
    58→    if (r.type === 'simplex') {
    59→      simplexRepeaters.push(r);
    60→    } else {
    61→      const blCode = r.bundesland_code || '_other';
    62→      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
    63→      repeatersByBl[blCode].push(r);
    64→      if (r.is_linked) linkedRepeaters.push(r);
    65→    }
    66→  }
    67→
    68→  // Sort Bundesland codes
    69→  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    70→    if (a === '_other') return 1;
    71→    if (b === '_other') return -1;
    72→    return a.localeCompare(b);
    73→  });
    74→
    75→  const parseRapport = (raw: string) => {
    76→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    77→    if (!match) return { readability: null, strength: null, db_over_s9: null };
    78→    return {
    79→      readability: parseInt(match[1]),
    80→      strength: parseInt(match[2]),
    81→      db_over_s9: match[3]?.trim() || null,
    82→    };
    83→  };
    84→
    85→  const handleSubmit = async (e: FormEvent) => {
    86→    e.preventDefault();
    87→    if (!activeRepeaterId) return;
    88→    const operator = await getOrCreateOperator(callsign, selectedOperator);
    89→    if (!operator) return;
    90→    setSelectedOperator(operator);
    91→
    92→    const parsed = parseRapport(rapport);
    93→
    94→    if (editingId) {
    95→      try {
    96→        const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
    97→          method: 'PATCH',
    98→          body: JSON.stringify({ ...parsed, notes: notes || null }),
    99→        });
   100→        onReportUpdated(updated);
   101→        setEditingId(null);
   102→      } catch {}
   103→    } else {
   104→      try {
   105→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   106→          method: 'POST',
   107→          body: JSON.stringify({
   108→            operator_id: operator.id,
   109→            repeater_id: activeRepeaterId,
   110→            ...parsed,
   111→            notes: notes || null,
   112→          }),
   113→        });
   114→        onReportCreated(report);
   115→
   116→        // Cross-repeater sync: create placeholder entries on other repeaters
   117→        for (const rep of repeaters) {
   118→          if (rep.repeater_id !== activeRepeaterId) {
   119→            const exists = reports.some(r => r.operator_id === operator.id && r.repeater_id === rep.repeater_id);
   120→            if (!exists) {
   121→              try {
   122→                const placeholder = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   123→                  method: 'POST',
   124→                  body: JSON.stringify({
   125→                    operator_id: operator.id,
   126→                    repeater_id: rep.repeater_id,
   127→                  }),
   128→                });
   129→                onReportCreated(placeholder);
   130→              } catch {}
   131→            }
   132→          }
   133→        }
   134→      } catch (err: any) {
   135→        if (err.message?.includes('existiert')) {
   136→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === activeRepeaterId);
   137→          if (existing) {
   138→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   139→              method: 'PATCH',
   140→              body: JSON.stringify({ ...parsed, notes: notes || null }),
   141→            });
   142→            onReportUpdated(updated);
   143→          }
   144→        }
   145→      }
   146→    }
   147→
   148→    setCallsign('');
   149→    setSelectedOperator(null);
   150→    setRapport('');
   151→    setNotes('');
   152→  };
   153→
   154→  const handleEdit = (report: any) => {
   155→    setEditingId(report.id);
   156→    setCallsign(report.callsign);
   157→    setSelectedOperator({ id: report.operator_id, callsign: report.callsign });
   158→    const rapportStr = report.readability && report.strength
   159→      ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}`
   160→      : '';
   161→    setRapport(rapportStr);
   162→    setNotes(report.notes || '');
   163→  };
   164→
   165→  const handleDelete = async (reportId: number) => {
   166→    if (!confirm('Rapport löschen?')) return;
   167→    try {
   168→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   169→      onReportDeleted(reportId);
   170→    } catch {}
   171→  };
   172→
   173→  // Group reports by Bezirk
   174→  const reportsByBezirk: Record<string, any[]> = {};
   175→  for (const r of repeaterReports) {
   176→    const key = r.bezirk_code || '_other';
   177→    if (!reportsByBezirk[key]) reportsByBezirk[key] = [];
   178→    reportsByBezirk[key].push(r);
   179→  }
   180→
   181→  return (
   182→    <div className="space-y-3">
   183→      {/* Repeater tabs grouped by Bundesland */}
   184→      <div className="space-y-1">
   185→        {sortedBlCodes.map(blCode => {
   186→          const blReps = repeatersByBl[blCode];
   187→          const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
   188→          return (
   189→            <div key={blCode}>
   190→              <div className="px-1 mb-0.5">
   191→                <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
   192→              </div>
   193→              <div className="flex flex-wrap gap-1 mb-1">
   194→                {blReps.map(r => {
   195→                  const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
   196→                  return (
   197→                    <button
   198→                      key={r.repeater_id}
   199→                      onClick={() => setActiveRepeaterId(r.repeater_id)}
   200→                      className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#5b3a1a] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
   201→                    >
   202→                      {r.short_name}
   203→                      {r.operator_callsign && (
   204→                        <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
   205→                          {r.operator_callsign}
   206→                        </span>
   207→                      )}
   208→                      {repReportCount > 0 && (
   209→                        <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
   210→                          {repReportCount}
   211→                        </span>
   212→                      )}
   213→                    </button>
   214→                  );
   215→                })}
   216→              </div>
   217→            </div>
   218→          );
   219→        })}
   220→
   221→        {/* Simplex tabs */}
   222→        {simplexRepeaters.length > 0 && (
   223→          <div>
   224→            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">Simplex</div>
   225→            <div className="flex flex-wrap gap-1 mb-1">
   226→              {simplexRepeaters.map(r => {
   227→                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
   228→                return (
   229→                  <button
   230→                    key={r.repeater_id}
   231→                    onClick={() => setActiveRepeaterId(r.repeater_id)}
   232→                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#5b3a1a] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
   233→                  >
   234→                    {r.short_name}
   235→                    {r.operator_callsign && (
   236→                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
   237→                        {r.operator_callsign}
   238→                      </span>
   239→                    )}
   240→                    {repReportCount > 0 && (
   241→                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
   242→                        {repReportCount}
   243→                      </span>
   244→                    )}
   245→                  </button>
   246→                );
   247→              })}
   248→            </div>
   249→          </div>
   250→        )}
   251→
   252→        {/* OE-Link tabs */}
   253→        {linkedRepeaters.length > 0 && (
   254→          <div>
   255→            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">OE-Link</div>
   256→            <div className="flex flex-wrap gap-1 mb-1">
   257→              {linkedRepeaters.map(r => {
   258→                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
   259→                return (
   260→                  <button
   261→                    key={`oelink-${r.repeater_id}`}
   262→                    onClick={() => setActiveRepeaterId(r.repeater_id)}
   263→                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-blue-700 text-white font-medium' : 'bg-blue-50 text-blue-800 hover:bg-blue-100 border border-blue-200'}`}
   264→                  >
   265→                    {r.short_name}
   266→                    {r.operator_callsign && (
   267→                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-100 text-blue-700'}`}>
   268→                        {r.operator_callsign}
   269→                      </span>
   270→                    )}
   271→                    {repReportCount > 0 && (
   272→                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-200'}`}>
   273→                        {repReportCount}
   274→                      </span>
   275→                    )}
   276→                  </button>
   277→                );
   278→              })}
   279→            </div>
   280→          </div>
   281→        )}
   282→      </div>
   283→
   284→      {/* Repeater info */}
