   286→        <div className="text-xs text-gray-500 flex gap-4">
   287→          {activeRepeater.frequency_mhz && <span>{activeRepeater.frequency_mhz} MHz</span>}
   288→          {activeRepeater.offset_mhz && <span>Offset: {activeRepeater.offset_mhz > 0 ? '+' : ''}{activeRepeater.offset_mhz} MHz</span>}
   289→          {activeRepeater.ctcss_hz && <span>CTCSS: {activeRepeater.ctcss_hz} Hz</span>}
   290→          {activeRepeater.burst_hz && <span>Burst: {activeRepeater.burst_hz} Hz</span>}
   291→          {activeRepeater.repeater_callsign && <span className="font-mono">{activeRepeater.repeater_callsign}</span>}
