   258→                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
   259→                      />
   260→                      <input
   261→                        type="text"
   262→                        value={newRepCallsign}
   263→                        onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
   264→                        placeholder="Rufz."
   265→                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
   266→                      />
   267→                      <button
   268→                        onClick={() => addRepeater(bl.code)}
   269→                        className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
   270→                      >
   271→                        OK
   272→                      </button>
