                      <LandBezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        onSubmit={(form) => handleBezirkSubmit(bz.code, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                      />
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
