const db = require('better-sqlite3')('/data/bosarsalog.db');
const crypto = require('crypto');

// Fix Gerlitze -> Gerlitzen
db.prepare(\\\"UPDATE repeaters SET short_name = 'Gerlitzen 2m', site_name = 'Gerlitzen' WHERE id = 265\\\").run();
db.prepare(\\\"UPDATE repeaters SET short_name = 'Gerlitzen 70cm', site_name = 'Gerlitzen' WHERE id = 266\\\").run();
console.log('Fixed Gerlitze -> Gerlitzen');

// Delete all data
db.prepare(\\\"DELETE FROM signal_reports\\\").run();
db.prepare(\\\"DELETE FROM exercise_attendance\\\").run();
db.prepare(\\\"DELETE FROM exercise_repeaters\\\").run();
db.prepare(\\\"DELETE FROM exercises\\\").run();
db.prepare(\\\"DELETE FROM operators\\\").run();
console.log('Deleted all data');

