  const [showParticipants, setShowParticipants] = useState(false);

  useEffect(() => {
    if (!id) return;
    Promise.all([
      apiFetch(`/api/v1/exercises/${id}`),
      apiFetch(`/api/v1/exercises/${id}/stats`),
    ]).then(([ex, st]) => {
      setExercise(ex);
      setStats(st);
