     1→import { useState, useEffect, useCallback, useRef } from 'react';
     2→import { useParams, Link } from 'react-router-dom';
     3→import { apiFetch } from '../services/api';
     4→import { getSocket } from '../services/socket';
     5→import LandMode from '../components/LandMode';
     6→import BundMode from '../components/BundMode';
     7→import RunningTotals from '../components/RunningTotals';
     8→
     9→interface Stats {
    10→  totalParticipants: number;
    11→  totalReports: number;
    12→  perRepeater: { short_name: string; count: number }[];
    13→}
    14→
    15→export default function ExercisePage() {
    16→  const { id } = useParams<{ id: string }>();
    17→  const [exercise, setExercise] = useState<any>(null);
    18→  const [mode, setMode] = useState<'land' | 'bund'>('land');
    19→  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
    20→  const [reports, setReports] = useState<any[]>([]);
    21→  const [loading, setLoading] = useState(true);
    22→  const [opCallsign, setOpCallsign] = useState('');
    23→  const socketRef = useRef(getSocket());
    24→
    25→  const refreshStats = useCallback(async () => {
    26→    if (!id) return;
    27→    try {
    28→      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
    29→      setStats(s);
    30→    } catch {}
    31→  }, [id]);
    32→
    33→  useEffect(() => {
    34→    if (!id) return;
    35→    setLoading(true);
    36→    apiFetch(`/api/v1/exercises/${id}`)
    37→      .then(data => {
    38→        setExercise(data);
    39→        setReports(data.reports || []);
    40→        const firstOp = (data.repeaters || []).find((r: any) => r.operator_callsign);
    41→        if (firstOp) setOpCallsign(firstOp.operator_callsign);
    42→      })
    43→      .catch(() => {})
    44→      .finally(() => setLoading(false));
    45→    refreshStats();
    46→  }, [id, refreshStats]);
    47→
    48→  useEffect(() => {
    49→    if (!id) return;
    50→    const socket = socketRef.current;
    51→    socket.emit('join_exercise', { exercise_id: id });
    52→
    53→    socket.on('report_created', (data: any) => {
    54→      setReports(prev => [data, ...prev]);
    55→      refreshStats();
    56→    });
    57→    socket.on('report_updated', (data: any) => {
    58→      setReports(prev => prev.map(r => r.id === data.id ? data : r));
    59→      refreshStats();
    60→    });
    61→    socket.on('report_deleted', (data: any) => {
    62→      setReports(prev => prev.filter(r => r.id !== data.report_id));
    63→      refreshStats();
    64→    });
    65→
    66→    return () => {
    67→      socket.emit('leave_exercise', { exercise_id: id });
    68→      socket.off('report_created');
    69→      socket.off('report_updated');
    70→      socket.off('report_deleted');
    71→    };
    72→  }, [id, refreshStats]);
    73→
    74→  const handleReportCreated = useCallback((report: any) => {
    75→    setReports(prev => [report, ...prev]);
    76→    socketRef.current.emit('report_created', { ...report, exercise_id: id! });
    77→    refreshStats();
    78→  }, [id, refreshStats]);
    79→
    80→  const handleReportUpdated = useCallback((report: any) => {
    81→    setReports(prev => prev.map(r => r.id === report.id ? report : r));
    82→    socketRef.current.emit('report_updated', { ...report, exercise_id: id! });
    83→    refreshStats();
    84→  }, [id, refreshStats]);
    85→
    86→  const handleReportDeleted = useCallback((reportId: number) => {
    87→    setReports(prev => prev.filter(r => r.id !== reportId));
    88→    socketRef.current.emit('report_deleted', { report_id: reportId, exercise_id: id! });
    89→    refreshStats();
    90→  }, [id, refreshStats]);
    91→
    92→  const updateOpCallsign = async (val: string) => {
    93→    const reps = exercise?.repeaters || [];
    94→    for (const r of reps) {
    95→      await apiFetch(`/api/v1/exercises/${id}/repeaters/${r.repeater_id}`, {
    96→        method: 'PATCH',
    97→        body: JSON.stringify({ operator_callsign: val || null }),
    98→      });
    99→    }
   100→    setExercise((prev: any) => prev ? {
   101→      ...prev,
   102→      repeaters: prev.repeaters?.map((r: any) => ({ ...r, operator_callsign: val || null })),
   103→    } : null);
   104→  };
   105→
   106→  if (loading) return <p className="text-gray-500 p-4">Laden...</p>;
   107→  if (!exercise) return <p className="text-red-500 p-4">Übung nicht gefunden</p>;
   108→
   109→  return (
   110→    <div className="space-y-4">
   111→      <div className="flex items-center justify-between flex-wrap gap-2">
   112→        <h1 className="text-xl font-bold text-[#5b3a1a]">
   113→          {exercise.name || 'Übung'} — {new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' })}
   114→        </h1>
   115→        <div className="flex items-center gap-2">
   116→          {mode === 'land' && (
   117→            <div className="flex items-center gap-1.5">
   118→              <label className="text-xs text-gray-500">OP:</label>
   119→              <input
   120→                type="text"
   121→                value={opCallsign}
   122→                onChange={e => setOpCallsign(e.target.value.toUpperCase())}
   123→                onBlur={e => updateOpCallsign(e.target.value.toUpperCase())}
   124→                placeholder="Rufzeichen"
   125→                className="border border-gray-300 rounded px-2 py-1 text-sm font-mono uppercase w-28 focus:outline-none focus:ring-2 focus:ring-amber-500"
   126→              />
   127→            </div>
   128→          )}
   129→          <Link to={`/exercises/${id}/setup`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-1 rounded text-sm">
   130→            Einrichten
   131→          </Link>
   132→          <Link to={`/exercises/${id}/reports`} className="bg-amber-100 hover:bg-amber-200 text-amber-800 px-3 py-1 rounded text-sm">
   133→            Auswertung
   134→          </Link>
   135→        </div>
   136→      </div>
   137→
   138→      <RunningTotals stats={stats} />
   139→
   140→      <div className="flex gap-1 bg-white rounded-lg p-1 shadow-sm w-fit">
   141→        <button
   142→          onClick={() => setMode('land')}
   143→          className={`px-4 py-1.5 rounded text-sm font-medium ${mode === 'land' ? 'bg-[#5b3a1a] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
   144→        >
   145→          Land (Umsetzer)
   146→        </button>
   147→        <button
   148→          onClick={() => setMode('bund')}
   149→          className={`px-4 py-1.5 rounded text-sm font-medium ${mode === 'bund' ? 'bg-[#5b3a1a] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
   150→        >
   151→          Bund (Bundesland)
   152→        </button>
   153→      </div>
   154→
   155→      {mode === 'land' ? (
   156→        <LandMode
   157→          exerciseId={id!}
   158→          repeaters={exercise.repeaters || []}
   159→          reports={reports}
   160→          onReportCreated={handleReportCreated}
   161→          onReportUpdated={handleReportUpdated}
   162→          onReportDeleted={handleReportDeleted}
   163→        />
   164→      ) : (
   165→        <BundMode
   166→          exerciseId={id!}
   167→          reports={reports}
   168→          onReportCreated={handleReportCreated}
   169→          onReportUpdated={handleReportUpdated}
   170→          onReportDeleted={handleReportDeleted}
   171→        />
   172→      )}
   173→    </div>
   174→  );
   175→}
