    34→export default function DashboardPage() {
    35→  const { admin } = useAuth();
    36→  const navigate = useNavigate();
    37→  const [exercises, setExercises] = useState<ExerciseSummary[]>([]);
    38→  const [loading, setLoading] = useState(true);
    39→  const [showCreate, setShowCreate] = useState(false);
    40→  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
    41→  const [newName, setNewName] = useState(EXERCISE_TYPES[0]);
    42→  const [creating, setCreating] = useState(false);
    43→
    44→  useEffect(() => {
    45→    apiFetch('/api/v1/exercises')
    46→      .then(data => setExercises(data))
    47→      .catch(() => {})
    48→      .finally(() => setLoading(false));
    49→  }, []);
    50→
    51→  const formatDate = (d: string) => {
    52→    const date = new Date(d + 'T00:00:00');
    53→    return date.toLocaleDateString('de-AT', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
    54→  };
    55→
    56→  // Compute nearest exercise to today
    57→  const today = new Date().toISOString().split('T')[0];
    58→  const nearestId = exercises.length > 0
    59→    ? exercises.reduce((closest, e) => {
    60→        const dCur = Math.abs(new Date(e.date).getTime() - new Date(today).getTime());
    61→        const dBest = Math.abs(new Date(closest.date).getTime() - new Date(today).getTime());
    62→        return dCur < dBest ? e : closest;
    63→      }, exercises[0]).id
    64→    : null;
    65→
    66→  // Compute quarterly and yearly totals
    67→  const quarterTotals: Record<number, { participants: number; reports: number }> = {};
    68→  let yearParticipants = 0;
    69→  let yearReports = 0;
    70→
    71→  for (const ex of exercises) {
    72→    const q = getQuarter(ex.date);
    73→    if (!quarterTotals[q]) quarterTotals[q] = { participants: 0, reports: 0 };
    74→    quarterTotals[q].participants += ex.participant_count;
    75→    quarterTotals[q].reports += ex.report_count;
    76→    yearParticipants += ex.participant_count;
    77→    yearReports += ex.report_count;
    78→  }
    79→
    80→  // Build rows with quarter subtotals inserted
    81→  const buildRows = () => {
    82→    const rows: { type: 'exercise' | 'quarter' | 'year'; data?: ExerciseSummary; quarter?: number; participants?: number; reports?: number }[] = [];
