    95→        rows.push({ type: 'quarter', quarter: q, ...quarterTotals[q] });
    96→        lastQuarter = q;
    97→      }
    98→    }
    99→
   100→    // Yearly total
   101→    if (exercises.length > 0) {
   102→      rows.push({ type: 'year', participants: yearParticipants, reports: yearReports });
   103→    }
   104→
   105→    return rows;
   106→  };
   107→
