   216→      )}
   217→
   218→      {/* Trend chart */}
   219→      {!loading && exercises.length > 0 && (
   220→        <div className="bg-white rounded-xl shadow p-4 mb-6">
   221→          <h2 className="text-sm font-semibold text-[#5b3a1a] mb-3">BOS-ARSA Krisenkommunikationsübungen {new Date().getFullYear()}</h2>
