     1→import { useState, useEffect, type FormEvent } from 'react';
     2→import { apiFetch, getOrCreateOperator } from '../services/api';
     3→import CallsignInput from './CallsignInput';
     4→
     5→interface Props {
     6→  exerciseId: string;
     7→  reports: any[];
     8→  onReportCreated: (report: any) => void;
     9→  onReportUpdated: (report: any) => void;
    10→  onReportDeleted: (reportId: number) => void;
    11→}
    12→
    13→interface EntryForm {
    14→  callsign: string;
    15→  operator: any;
    16→  rapport: string;
    17→  notes: string;
    18→}
    19→
    20→export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    21→  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
    22→  const [bezirke, setBezirke] = useState<any[]>([]);
    23→  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
    24→  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
    25→  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
    26→  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
    27→  const [addRepBl, setAddRepBl] = useState<string | null>(null);
    28→  const [newRepName, setNewRepName] = useState('');
    29→  const [newRepFreq, setNewRepFreq] = useState('');
    30→  const [newRepCallsign, setNewRepCallsign] = useState('');
    31→  const [editingId, setEditingId] = useState<number | null>(null);
    32→  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
    33→
    34→  useEffect(() => {
    35→    Promise.all([
    36→      apiFetch('/api/v1/reference/bundeslaender'),
    37→      apiFetch('/api/v1/reference/bezirke'),
    38→      apiFetch('/api/v1/repeaters'),
    39→      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    40→    ]).then(([bl, bz, allReps, exReps]) => {
    41→      setBundeslaender(bl);
    42→      setBezirke(bz);
    43→      const linked = allReps.filter((r: any) => r.is_linked);
    44→      setLinkedRepeaters(linked);
    45→      // Initialize per-BL defaults: first linked in that BL, else first overall
    46→      const defaults: Record<string, number> = {};
    47→      const ops: Record<string, string> = {};
    48→      for (const b of bl) {
    49→        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
    50→        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
    51→        defaults[b.code] = repId;
    52→        // Load existing OP callsign from exercise_repeaters
    53→        const exRep = exReps.find((er: any) => er.repeater_id === repId);
    54→        ops[b.code] = exRep?.operator_callsign || '';
    55→      }
    56→      setBlRepSelection(defaults);
    57→      setBlOpCallsigns(ops);
    58→    }).catch(() => {});
    59→  }, [exerciseId]);
    60→
    61→  const saveOpCallsign = async (blCode: string, val: string) => {
    62→    const repId = blRepSelection[blCode];
    63→    if (!repId) return;
    64→    try {
    65→      // Ensure exercise_repeater exists, then update
    66→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
    67→        method: 'POST',
    68→        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
    69→      });
    70→    } catch {
    71→      // Already exists, just patch
    72→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
    73→        method: 'PATCH',
    74→        body: JSON.stringify({ operator_callsign: val || null }),
    75→      });
    76→    }
    77→  };
    78→
    79→  const addRepeater = async (blCode: string) => {
    80→    if (!newRepName && !newRepFreq) return;
    81→    const name = newRepName || `Direkte ${newRepFreq}`;
    82→    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    83→    try {
    84→      const rep = await apiFetch('/api/v1/repeaters', {
    85→        method: 'POST',
    86→        body: JSON.stringify({
    87→          short_name: name,
    88→          site_name: name,
    89→          frequency_mhz: freq,
    90→          callsign: newRepCallsign || null,
    91→          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
    92→          type: 'repeater',
    93→          bundesland_code: blCode,
    94→        }),
    95→      });
    96→      setLinkedRepeaters(prev => [...prev, rep]);
    97→      setNewRepName('');
    98→      setNewRepFreq('');
    99→      setNewRepCallsign('');
   100→      setAddRepBl(null);
   101→    } catch {}
   102→  };
   103→
   104→  const toggleBl = (code: string) => {
   105→    setCollapsedBl(prev => {
   106→      const next = new Set(prev);
   107→      if (next.has(code)) next.delete(code); else next.add(code);
   108→      return next;
   109→    });
   110→  };
   111→
   112→  const parseRapport = (raw: string) => {
   113→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
   114→    if (!match) return { readability: null, strength: null, db_over_s9: null };
   115→    return {
   116→      readability: parseInt(match[1]),
   117→      strength: parseInt(match[2]),
   118→      db_over_s9: match[3]?.trim() || null,
   119→    };
   120→  };
   121→
   122→  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
   123→    if (!repeaterId) return;
   124→    const operator = await getOrCreateOperator(form.callsign, form.operator);
   125→    if (!operator) return;
   126→
   127→    const parsed = parseRapport(form.rapport);
   128→
   129→    try {
   130→      const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   131→        method: 'POST',
   132→        body: JSON.stringify({
   133→          operator_id: operator.id,
   134→          repeater_id: repeaterId,
   135→          ...parsed,
   136→          notes: form.notes || null,
   137→        }),
   138→      });
   139→      onReportCreated(report);
   140→    } catch (err: any) {
   141→      if (err.message?.includes('existiert')) {
   142→        const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
   143→        if (existing) {
   144→          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   145→            method: 'PATCH',
   146→            body: JSON.stringify({ ...parsed, notes: form.notes || null }),
   147→          });
   148→          onReportUpdated(updated);
   149→        }
   150→      }
   151→    }
   152→  };
   153→
   154→  const handleEdit = (report: any) => {
   155→    setEditingId(report.id);
   156→    setEditForm({
   157→      callsign: report.callsign,
   158→      operator: { id: report.operator_id, callsign: report.callsign },
   159→      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
   160→      notes: report.notes || '',
   161→    });
   162→  };
   163→
   164→  const handleUpdate = async () => {
   165→    if (!editingId) return;
   166→    const parsed = parseRapport(editForm.rapport);
   167→    try {
   168→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   169→        method: 'PATCH',
   170→        body: JSON.stringify({ ...parsed, notes: editForm.notes || null }),
   171→      });
   172→      onReportUpdated(updated);
   173→      setEditingId(null);
   174→    } catch {}
   175→  };
   176→
   177→  const handleDelete = async (reportId: number) => {
   178→    if (!confirm('Rapport löschen?')) return;
   179→    try {
   180→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   181→      onReportDeleted(reportId);
   182→    } catch {}
   183→  };
   184→
   185→  return (
   186→    <div className="space-y-2">
   187→      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
   188→        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
   189→        const defaultRepId = blRepSelection[bl.code] || 0;
   190→        const blReports = reports.filter(r => r.bundesland_code === bl.code);
   191→        const isCollapsed = collapsedBl.has(bl.code);
   192→        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;
   193→
   194→        return (
   195→          <div key={bl.code} className="bg-white rounded-lg shadow-sm overflow-hidden">
   196→            <div className="bg-gray-50 px-3 py-2 flex items-center justify-between border-b">
   197→              <div
   198→                onClick={() => toggleBl(bl.code)}
   199→                className="flex items-center gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1"
   200→              >
   201→                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
   202→                <span className="font-medium text-sm">{bl.name}</span>
   203→                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full">{reportCount}</span>
   204→              </div>
   205→              <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
   206→                <label className="text-xs text-gray-500">OP:</label>
   207→                <input
   208→                  type="text"
   209→                  value={blOpCallsigns[bl.code] || ''}
   210→                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
   211→                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
   212→                  placeholder="Rufzeichen"
   213→                  className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-24 focus:outline-none focus:ring-1 focus:ring-amber-500"
   214→                />
   215→              </div>
   216→            </div>
   217→
   218→            {!isCollapsed && (
   219→              <div>
   220→                <div className="divide-y divide-gray-100">
   221→                  {blBezirke.map(bz => {
   222→                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
   223→                    return (
   224→                      <BezirkRow
   225→                        key={bz.code}
   226→                        bezirk={bz}
   227→                        reports={bzReports}
   228→                        linkedRepeaters={linkedRepeaters}
   229→                        defaultRepeaterId={defaultRepId}
   230→                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
   231→                        onEdit={handleEdit}
   232→                        onDelete={handleDelete}
   233→                        editingId={editingId}
   234→                        editForm={editForm}
   235→                        onEditChange={setEditForm}
   236→                        onEditSave={handleUpdate}
   237→                        onEditCancel={() => setEditingId(null)}
   238→                      />
   239→                    );
   240→                  })}
   241→                </div>
   242→                <div className="px-3 py-1.5 border-t border-gray-100">
   243→                  {addRepBl === bl.code ? (
   244→                    <div className="flex items-center gap-1 flex-wrap">
   245→                      <input
   246→                        type="text"
   247→                        value={newRepName}
   248→                        onChange={e => setNewRepName(e.target.value)}
   249→                        placeholder="Name"
   250→                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-amber-500"
   251→                        autoFocus
   252→                      />
   253→                      <input
   254→                        type="text"
   255→                        value={newRepFreq}
   256→                        onChange={e => setNewRepFreq(e.target.value)}
   257→                        placeholder="MHz"
   258→                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
   259→                      />
   260→                      <input
   261→                        type="text"
   262→                        value={newRepCallsign}
   263→                        onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
   264→                        placeholder="Rufz."
   265→                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
   266→                      />
   267→                      <button
   268→                        onClick={() => addRepeater(bl.code)}
   269→                        className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
   270→                      >
   271→                        OK
   272→                      </button>
   273→                      <button
   274→                        onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
   275→                        className="text-gray-400 hover:text-gray-600 text-xs"
   276→                      >
   277→                        Abbrechen
   278→                      </button>
   279→                    </div>
   280→                  ) : (
   281→                    <button
   282→                      onClick={() => setAddRepBl(bl.code)}
   283→                      className="text-xs text-gray-400 hover:text-gray-600"
   284→                    >
   285→                      + Umsetzer hinzufügen
   286→                    </button>
   287→                  )}
   288→                </div>
   289→              </div>
   290→            )}
   291→          </div>
   292→        );
   293→      })}
   294→    </div>
   295→  );
   296→}
   297→
   298→interface BezirkRowProps {
   299→  bezirk: any;
   300→  reports: any[];
   301→  linkedRepeaters: any[];
   302→  defaultRepeaterId: number;
   303→  onSubmit: (repeaterId: number, form: EntryForm) => void;
   304→  onEdit: (report: any) => void;
   305→  onDelete: (id: number) => void;
   306→  editingId: number | null;
   307→  editForm: EntryForm;
   308→  onEditChange: (form: EntryForm) => void;
   309→  onEditSave: () => void;
   310→  onEditCancel: () => void;
   311→}
   312→
   313→function BezirkRow({ bezirk, reports, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
   314→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
   315→  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
   316→
   317→  useEffect(() => {
   318→    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
   319→  }, [defaultRepeaterId]);
   320→
   321→  const handleSubmit = (e: FormEvent) => {
   322→    e.preventDefault();
   323→    if ((!form.operator && !form.callsign) || !repeaterId) return;
   324→    onSubmit(repeaterId, form);
   325→    setForm({ callsign: '', operator: null, rapport: '', notes: '' });
   326→  };
   327→
   328→  return (
   329→    <div className="px-3 py-1.5">
   330→      <div className="flex items-center gap-2 mb-1">
   331→        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   332→          {bezirk.code}
   333→        </span>
   334→        <span className="text-xs text-gray-500">{bezirk.name}</span>
   335→      </div>
   336→
   337→      <div className="flex flex-wrap gap-1 mb-1">
   338→        {reports.map(r => (
   339→          <div key={r.id} className="group">
   340→            {editingId === r.id ? (
