                ) : (
                  <>
                    <td className="px-3 py-1.5 font-mono font-medium">{op.callsign}</td>
                    <td className="px-3 py-1.5">{op.name}</td>
                    <td className="px-3 py-1.5 text-gray-500">{op.qth}</td>
                    <td className="px-3 py-1.5">
                      {op.bezirk_code && (
