        </table>
      </div>

      {!search && (
        <div className="flex items-center justify-center gap-4">
          <button onClick={() => handlePage(-1)} disabled={page === 0} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Zurück
          </button>
          <span className="text-sm text-gray-400">Seite {page + 1}</span>
          <button onClick={() => handlePage(1)} disabled={operators.length < 50} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Weiter
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { apiFetch } from '../services/api';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement, PointElement, LineElement,
  Title, Tooltip, Legend, Filler,
} from 'chart.js';
import { Bar, Line } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const EXERCISE_TYPES = [
  'Krisenkommunikationsübung',
  'Notfunkübung',
  'Feldtag',
  'Relaisfunktest',
];

interface ExerciseSummary {
  id: string;
  name: string | null;
  date: string;
  participant_count: number;
  report_count: number;
}

function getQuarter(date: string): number {
  const month = new Date(date + 'T00:00:00').getMonth();
  return Math.floor(month / 3) + 1;
}

export default function DashboardPage() {
  const { admin } = useAuth();
  const navigate = useNavigate();
  const [exercises, setExercises] = useState<ExerciseSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [newName, setNewName] = useState(EXERCISE_TYPES[0]);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    apiFetch('/api/v1/exercises')
      .then(data => setExercises(data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const formatDate = (d: string) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-AT', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
  };

  // Compute nearest exercise to today
  const today = new Date().toISOString().split('T')[0];
  const nearestId = exercises.length > 0
    ? exercises.reduce((closest, e) => {
        const dCur = Math.abs(new Date(e.date).getTime() - new Date(today).getTime());
        const dBest = Math.abs(new Date(closest.date).getTime() - new Date(today).getTime());
        return dCur < dBest ? e : closest;
      }, exercises[0]).id
    : null;

  // Compute quarterly and yearly totals
  const quarterTotals: Record<number, { participants: number; reports: number }> = {};
  let yearParticipants = 0;
  let yearReports = 0;

  for (const ex of exercises) {
    const q = getQuarter(ex.date);
    if (!quarterTotals[q]) quarterTotals[q] = { participants: 0, reports: 0 };
    quarterTotals[q].participants += ex.participant_count;
    quarterTotals[q].reports += ex.report_count;
    yearParticipants += ex.participant_count;
    yearReports += ex.report_count;
  }

  // Build rows with quarter subtotals inserted
  const buildRows = () => {
    const rows: { type: 'exercise' | 'quarter' | 'year'; data?: ExerciseSummary; quarter?: number; participants?: number; reports?: number }[] = [];
    let lastQuarter = 0;

    for (let i = 0; i < exercises.length; i++) {
      const ex = exercises[i];
      const q = getQuarter(ex.date);
      const nextEx = exercises[i + 1];
      const nextQ = nextEx ? getQuarter(nextEx.date) : 0;

      rows.push({ type: 'exercise', data: ex });

      // Insert quarter subtotal when quarter changes or at last exercise
      if (q !== nextQ && quarterTotals[q]) {
        rows.push({ type: 'quarter', quarter: q, ...quarterTotals[q] });
        lastQuarter = q;
      }
    }

    // Yearly total
    if (exercises.length > 0) {
      rows.push({ type: 'year', participants: yearParticipants, reports: yearReports });
    }

    return rows;
  };

  const QUARTER_LABELS: Record<number, string> = { 1: 'Q1 (Jan-Mär)', 2: 'Q2 (Apr-Jun)', 3: 'Q3 (Jul-Sep)', 4: 'Q4 (Okt-Dez)' };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[#5b3a1a]">Gesamtübersicht</h1>
          <p className="text-sm text-gray-500">Willkommen, {admin?.username}</p>
        </div>
        {admin?.role === 'admin' && (
          <button
            onClick={() => setShowCreate(v => !v)}
            className="bg-[#5b3a1a] hover:bg-[#7a5230] text-white px-4 py-2 rounded-lg text-sm font-medium"
          >
            + Neue Übung
          </button>
        )}
      </div>

      {showCreate && (
        <div className="bg-white rounded-xl shadow p-4 mb-6">
          <h2 className="text-sm font-semibold text-[#5b3a1a] mb-3">Neue Übung anlegen</h2>
          <div className="flex items-end gap-3 flex-wrap">
            <div>
              <label className="block text-xs text-gray-500 mb-1">Datum</label>
              <input
                type="date"
                value={newDate}
                onChange={e => setNewDate(e.target.value)}
                className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
              />
            </div>
            <div className="flex-1 min-w-[200px]">
              <label className="block text-xs text-gray-500 mb-1">Typ / Name</label>
              <div className="flex gap-2">
                <select
                  value={EXERCISE_TYPES.includes(newName) ? newName : ''}
                  onChange={e => setNewName(e.target.value)}
                  className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                >
                  {EXERCISE_TYPES.map(t => (
                    <option key={t} value={t}>{t}</option>
                  ))}
                  <option value="">Eigener Name...</option>
                </select>
                {!EXERCISE_TYPES.includes(newName) && (
                  <input
                    type="text"
                    value={newName}
                    onChange={e => setNewName(e.target.value)}
                    placeholder="Name der Übung"
                    className="border border-gray-300 rounded px-2 py-1.5 text-sm flex-1 focus:outline-none focus:ring-2 focus:ring-amber-500"
                    autoFocus
                  />
                )}
              </div>
            </div>
            <button
              disabled={creating || !newDate || !newName}
              onClick={async () => {
                setCreating(true);
                try {
                  const ex = await apiFetch('/api/v1/exercises', {
                    method: 'POST',
                    body: JSON.stringify({ date: newDate, name: newName }),
                  });
                  navigate(`/exercises/${ex.id}/setup`);
                } catch {
                } finally {
                  setCreating(false);
                }
              }}
              className="bg-green-600 hover:bg-green-700 text-white px-4 py-1.5 rounded text-sm font-medium disabled:opacity-50"
            >
              {creating ? 'Erstellen...' : 'Erstellen'}
            </button>
            <button
              onClick={() => setShowCreate(false)}
              className="text-gray-500 text-sm hover:text-gray-700"
            >
              Abbrechen
            </button>
          </div>
        </div>
      )}

      {/* Summary cards */}
      {!loading && exercises.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#5b3a1a]">{exercises.length}</div>
            <div className="text-sm text-gray-500">Übungen</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#5b3a1a]">{yearParticipants}</div>
            <div className="text-sm text-gray-500">Teilnehmer gesamt</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#5b3a1a]">{yearReports}</div>
            <div className="text-sm text-gray-500">Rapporte gesamt</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-gray-600">
              {exercises.length > 0 ? Math.round(yearParticipants / exercises.filter(e => e.participant_count > 0).length || 1) : 0}
            </div>
            <div className="text-sm text-gray-500">Teilnehmer/Übung</div>
          </div>
        </div>
      )}

      {/* Trend chart */}
      {!loading && exercises.length > 0 && (
        <div className="bg-white rounded-xl shadow p-4 mb-6">
          <h2 className="text-sm font-semibold text-[#5b3a1a] mb-3">BOS-ARSA Krisenkommunikationsübungen {new Date().getFullYear()}</h2>
          <div style={{ height: 300 }}>
            <Bar
              data={{
                labels: exercises.map(e => {
                  const d = new Date(e.date + 'T00:00:00');
                  return d.toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit' });
                }),
                datasets: [
                  {
                    label: 'Teilnehmer',
                    data: exercises.map(e => e.participant_count),
                    backgroundColor: '#5b3a1a',
                  },
                  {
                    label: 'Rapporte',
                    data: exercises.map(e => e.report_count),
                    backgroundColor: '#d97706',
                  },
                ],
              }}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' },
                },
                scales: {
                  y: { beginAtZero: true },
                },
              }}
            />
          </div>
        </div>
      )}

      {loading ? (
        <p className="text-gray-500">Laden...</p>
      ) : exercises.length === 0 ? (
        <p className="text-gray-500">Noch keine Übungen erstellt.</p>
      ) : (
        <div className="bg-white rounded-xl shadow overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-[#5b3a1a] text-white">
              <tr>
                <th className="px-4 py-2 text-left">Datum</th>
                <th className="px-4 py-2 text-left">Name</th>
                <th className="px-4 py-2 text-right">Teilnehmer</th>
                <th className="px-4 py-2 text-right">Rapporte</th>
                <th className="px-4 py-2"></th>
              </tr>
            </thead>
            <tbody>
              {buildRows().map((row, idx) => {
                if (row.type === 'exercise') {
                  const ex = row.data!;
                  const isNearest = ex.id === nearestId;
                  return (
                    <tr key={ex.id} className={`border-t ${isNearest ? 'bg-amber-100 font-medium' : 'hover:bg-amber-50'}`}>
                      <td className="px-4 py-2 font-mono">
                        {formatDate(ex.date)}
                        {isNearest && <span className="ml-2 text-xs bg-amber-600 text-white px-1.5 py-0.5 rounded">Aktuell</span>}
                      </td>
                      <td className="px-4 py-2 text-gray-700">{ex.name || '—'}</td>
                      <td className="px-4 py-2 text-right">{ex.participant_count}</td>
                      <td className="px-4 py-2 text-right">{ex.report_count}</td>
                      <td className="px-4 py-2 text-right space-x-2">
                        <Link to={`/exercises/${ex.id}`} className="text-amber-700 hover:underline text-xs">
                          Öffnen
                        </Link>
                        <Link to={`/exercises/${ex.id}/reports`} className="text-blue-600 hover:underline text-xs">
                          Auswertung
                        </Link>
                      </td>
                    </tr>
                  );
                }
                if (row.type === 'quarter') {
                  return (
                    <tr key={`q${row.quarter}`} className="bg-blue-50 font-semibold border-t-2 border-blue-200">
                      <td className="px-4 py-1.5 text-blue-800 text-xs" colSpan={2}>
                        {QUARTER_LABELS[row.quarter!]}
                      </td>
                      <td className="px-4 py-1.5 text-right text-blue-800">{row.participants}</td>
                      <td className="px-4 py-1.5 text-right text-blue-800">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                if (row.type === 'year') {
                  return (
                    <tr key="year" className="bg-[#5b3a1a] text-white font-bold">
                      <td className="px-4 py-2" colSpan={2}>Jahresgesamt</td>
                      <td className="px-4 py-2 text-right">{row.participants}</td>
                      <td className="px-4 py-2 text-right">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                return null;
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../services/api';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement,
  ArcElement, PointElement, LineElement,
  Title, Tooltip, Legend,
} from 'chart.js';
import { Bar, Pie } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, PointElement, LineElement, Title, Tooltip, Legend);

interface BezirkStat {
  bundesland: string;
  bundesland_code: string;
  bezirk_code: string;
  bezirk_name: string;
  is_capital: number;
  participants: number;
  reports: number;
}

interface Participant {
  callsign: string;
  name: string | null;
  bezirk_code: string | null;
  bundesland_code: string | null;
  bundesland_name: string | null;
  report_count: number;
}

interface RepeaterStat {
  short_name: string;
  count: number;
}

interface BlStat {
  bundesland: string;
  bundesland_code: string;
  participants: number;
  reports: number;
}

interface Stats {
  totalParticipants: number;
  totalReports: number;
  perRepeater: RepeaterStat[];
  bezirkStats: BezirkStat[];
  blStats: BlStat[];
  participants: Participant[];
}

export default function ReportsPage() {
  const { id } = useParams<{ id: string }>();
  const [exercise, setExercise] = useState<any>(null);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [showParticipants, setShowParticipants] = useState(true);

  useEffect(() => {
    if (!id) return;
    Promise.all([
      apiFetch(`/api/v1/exercises/${id}`),
      apiFetch(`/api/v1/exercises/${id}/stats`),
    ]).then(([ex, st]) => {
      setExercise(ex);
      setStats(st);
    }).catch(() => {}).finally(() => setLoading(false));
  }, [id]);

  if (loading) return <p className="text-gray-500">Laden...</p>;
  if (!exercise) return <p className="text-red-500">Nicht gefunden</p>;

  // Group bezirk stats by Bundesland
  const byBl: Record<string, { name: string; bezirke: BezirkStat[]; totalParticipants: number; totalReports: number }> = {};
  if (stats) {
    for (const bz of stats.bezirkStats) {
      if (!byBl[bz.bundesland_code]) {
        byBl[bz.bundesland_code] = { name: bz.bundesland, bezirke: [], totalParticipants: 0, totalReports: 0 };
      }
      byBl[bz.bundesland_code].bezirke.push(bz);
      byBl[bz.bundesland_code].totalParticipants += bz.participants;
      byBl[bz.bundesland_code].totalReports += bz.reports;
    }
  }

  const formatDate = (d: string) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-AT', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-[#5b3a1a]">Auswertung</h1>
          <p className="text-sm text-gray-500">{exercise.name} — {formatDate(exercise.date)}</p>
        </div>
        <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-1.5 rounded text-sm">
          Zurück
        </Link>
      </div>

      {stats && (
        <>
          {/* Summary cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div className="bg-white rounded-lg shadow-sm p-4 text-center">
              <div className="text-3xl font-bold text-[#5b3a1a]">{stats.totalParticipants}</div>
              <div className="text-sm text-gray-500">Teilnehmer</div>
            </div>
            <div className="bg-white rounded-lg shadow-sm p-4 text-center">
              <div className="text-3xl font-bold text-[#5b3a1a]">{stats.totalReports}</div>
              <div className="text-sm text-gray-500">Rapporte</div>
            </div>
            {stats.perRepeater.map((r) => (
              <div key={r.short_name} className="bg-white rounded-lg shadow-sm p-4 text-center">
                <div className="text-2xl font-bold text-gray-700">{r.count}</div>
                <div className="text-xs text-gray-500">{r.short_name}</div>
              </div>
            ))}
          </div>

          {/* Charts */}
          {(() => {
            // Use bezirkStats if available, otherwise fall back to blStats (Bundesland level)
            const chartData = stats.bezirkStats.length > 0
              ? stats.bezirkStats.map(bz => ({ label: `${bz.bundesland} ${bz.bezirk_code}`, participants: bz.participants, reports: bz.reports }))
              : stats.blStats.map(bl => ({ label: bl.bundesland, participants: bl.participants, reports: bl.reports }));
            const chartLevel = stats.bezirkStats.length > 0 ? 'Bezirk' : 'Bundesland';

            return chartData.length > 0 ? (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              {/* Bar chart: Stationen + Rapporte */}
              <div className="bg-white rounded-xl shadow p-4">
                <h2 className="text-sm font-semibold text-[#5b3a1a] mb-3">
                  BOS-ARSA Krisenkommunikationsübung am {new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT')}
                </h2>
                <div style={{ height: 350 }}>
                  <Bar
                    data={{
                      labels: chartData.map(d => d.label),
                      datasets: [
                        {
                          label: 'Stationen',
                          data: chartData.map(d => d.participants),
                          backgroundColor: '#5b3a1a',
                        },
                        {
                          label: 'Rapporte',
                          data: chartData.map(d => d.reports),
                          backgroundColor: '#d97706',
                        },
                      ],
                    }}
                    options={{
                      responsive: true,
                      maintainAspectRatio: false,
                      plugins: { legend: { position: 'bottom' } },
                      scales: {
                        x: { ticks: { maxRotation: 90, minRotation: 45, font: { size: 9 } } },
                        y: { beginAtZero: true },
                      },
                    }}
                  />
                </div>
              </div>

