          {/* Participants list */}
          <div className="bg-white rounded-xl shadow overflow-hidden">
            <div
              onClick={() => setShowParticipants(v => !v)}
              className="bg-[#5b3a1a] text-white px-4 py-2 text-sm font-semibold cursor-pointer hover:bg-[#7a5230] flex items-center justify-between"
            >
              <span>Teilnehmer-Liste ({stats.participants.length})</span>
              <span className="text-xs">{showParticipants ? '▼' : '▶'}</span>
            </div>
            {showParticipants && (
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-gray-50 border-b text-left text-xs text-gray-500 uppercase">
                    <th className="px-4 py-2 w-8">#</th>
                    <th className="px-4 py-2">Rufzeichen</th>
                    <th className="px-4 py-2">Name</th>
                    <th className="px-4 py-2">Bezirk</th>
                    <th className="px-4 py-2">Bundesland</th>
                    <th className="px-4 py-2 text-right w-24">Rapporte</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {stats.participants.map((p, idx) => (
                    <tr key={p.callsign} className="hover:bg-amber-50">
                      <td className="px-4 py-1 text-xs text-gray-400">{idx + 1}</td>
                      <td className="px-4 py-1 font-mono font-medium">{p.callsign}</td>
                      <td className="px-4 py-1 text-gray-600">{p.name || ''}</td>
                      <td className="px-4 py-1">
                        {p.bezirk_code && (
                          <span className="text-xs bg-gray-200 rounded px-1.5 py-0.5 font-mono">{p.bezirk_code}</span>
                        )}
                      </td>
                      <td className="px-4 py-1 text-gray-600 text-xs">{p.bundesland_name || ''}</td>
                      <td className="px-4 py-1 text-right font-mono">{p.report_count}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>

          {/* Export buttons */}
          <div className="bg-white rounded-xl shadow p-4">
            <h2 className="text-sm font-semibold text-[#5b3a1a] mb-3">Export</h2>
            <div className="flex flex-wrap gap-3">
              <a
                href={`/api/v1/export/exercises/${id}/bund`}
                className="bg-amber-100 hover:bg-amber-200 text-amber-800 px-4 py-2 rounded text-sm font-medium"
                target="_blank"
              >
                TXT — Bund
              </a>
              <a
                href={`/api/v1/export/exercises/${id}/land`}
                className="bg-amber-100 hover:bg-amber-200 text-amber-800 px-4 py-2 rounded text-sm font-medium"
                target="_blank"
              >
                TXT — Land
              </a>
              <a
                href={`/api/v1/export/exercises/${id}/combined`}
                className="bg-amber-100 hover:bg-amber-200 text-amber-800 px-4 py-2 rounded text-sm font-medium"
                target="_blank"
              >
                TXT — Kombiniert
              </a>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { apiFetch } from '../services/api';

interface Props {
  value: string;
  onChange: (value: string) => void;
  onSelect: (operator: any) => void;
  autoFocus?: boolean;
  className?: string;
}

export default function CallsignInput({ value, onChange, onSelect, autoFocus, className }: Props) {
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIdx, setSelectedIdx] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  useEffect(() => {
    if (autoFocus && inputRef.current) inputRef.current.focus();
  }, [autoFocus]);

  const search = (q: string) => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (q.length < 2) { setSuggestions([]); setShowSuggestions(false); return; }
    debounceRef.current = setTimeout(async () => {
      try {
        const results = await apiFetch(`/api/v1/operators?q=${encodeURIComponent(q)}`);
        setSuggestions(results);
        setShowSuggestions(results.length > 0);
        setSelectedIdx(-1);
      } catch {}
    }, 150);
  };

  const handleChange = (val: string) => {
    const upper = val.toUpperCase();
    onChange(upper);
    search(upper);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIdx(prev => Math.min(prev + 1, suggestions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIdx(prev => Math.max(prev - 1, -1));
    } else if (e.key === 'Enter' && selectedIdx >= 0) {
      e.preventDefault();
      selectSuggestion(suggestions[selectedIdx]);
    } else if (e.key === 'Escape') {
      setShowSuggestions(false);
    }
    // Keyboard shortcuts
    if (e.altKey && e.key >= '1' && e.key <= '9') {
      e.preventDefault();
      onChange(value + `5/${e.key}`);
    }
    if (e.ctrlKey && e.key >= '1' && e.key <= '9') {
      e.preventDefault();
      onChange(`OE${e.key}`);
    }
  };

  const selectSuggestion = (op: any) => {
    onChange(op.callsign);
    onSelect(op);
    setShowSuggestions(false);
    setSuggestions([]);
  };

  return (
    <div className="relative">
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={e => handleChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
        onFocus={() => { if (suggestions.length > 0) setShowSuggestions(true); }}
        className={`border border-gray-300 rounded px-2 py-1 font-mono uppercase text-sm focus:outline-none focus:ring-2 focus:ring-amber-500 ${className || 'w-32'}`}
        placeholder="Rufzeichen"
      />
      {showSuggestions && (
        <div className="absolute z-20 top-full left-0 mt-1 bg-white border rounded shadow-lg max-h-48 overflow-auto w-64">
          {suggestions.map((op, i) => (
            <div
              key={op.id}
              onMouseDown={() => selectSuggestion(op)}
              className={`px-3 py-1.5 cursor-pointer text-sm ${i === selectedIdx ? 'bg-amber-100' : 'hover:bg-gray-100'}`}
            >
              <span className="font-mono font-bold">{op.callsign}</span>
              {op.name && <span className="ml-2 text-gray-500">{op.name}</span>}
              {op.bezirk_code && <span className="ml-1 text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import CallsignInput from './CallsignInput';

const BUNDESLAND_NAMES: Record<string, string> = {
  '01': 'OE1 Wien',
  '02': 'OE2 Salzburg',
  '03': 'OE3 Niederösterreich',
  '04': 'OE4 Burgenland',
  '05': 'OE5 Oberösterreich',
  '06': 'OE6 Steiermark',
  '07': 'OE7 Tirol',
  '08': 'OE8 Kärnten',
  '09': 'OE9 Vorarlberg',
  '10': 'Slowenien',
};

interface Props {
  exerciseId: string;
  repeaters: any[];
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

export default function LandMode({ exerciseId, repeaters, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [activeRepeaterId, setActiveRepeaterId] = useState<number | null>(null);

  // Entry form state
  const [callsign, setCallsign] = useState('');
  const [selectedOperator, setSelectedOperator] = useState<any>(null);
  const [rapport, setRapport] = useState('');
  const [notes, setNotes] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    if (repeaters.length > 0 && !activeRepeaterId) {
      setActiveRepeaterId(repeaters[0].repeater_id);
    }
  }, [repeaters, activeRepeaterId]);

  const activeRepeater = repeaters.find(r => r.repeater_id === activeRepeaterId);
  const repeaterReports = reports.filter(r => r.repeater_id === activeRepeaterId);

  // Group repeaters by Bundesland
  const repeatersByBl: Record<string, any[]> = {};
  const simplexRepeaters: any[] = [];
  const linkedRepeaters: any[] = [];
  for (const r of repeaters) {
    if (r.type === 'simplex') {
      simplexRepeaters.push(r);
    } else {
      const blCode = r.bundesland_code || '_other';
      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
      repeatersByBl[blCode].push(r);
      if (r.is_linked) linkedRepeaters.push(r);
    }
  }

  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    if (a === '_other') return 1;
    if (b === '_other') return -1;
    return a.localeCompare(b);
  });

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!activeRepeaterId) return;
    const operator = await getOrCreateOperator(callsign, selectedOperator);
    if (!operator) return;
    setSelectedOperator(operator);

    const parsed = parseRapport(rapport);

    if (editingId) {
      try {
        const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
          method: 'PATCH',
          body: JSON.stringify({ ...parsed, notes: notes || null }),
        });
        onReportUpdated(updated);
        setEditingId(null);
      } catch {}
    } else {
      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: activeRepeaterId,
            ...parsed,
            notes: notes || null,
          }),
        });
        onReportCreated(report);

        // Cross-repeater sync: create placeholder entries on other repeaters
        for (const rep of repeaters) {
          if (rep.repeater_id !== activeRepeaterId) {
            const exists = reports.some(r => r.operator_id === operator.id && r.repeater_id === rep.repeater_id);
            if (!exists) {
              try {
                const placeholder = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
                  method: 'POST',
                  body: JSON.stringify({
                    operator_id: operator.id,
                    repeater_id: rep.repeater_id,
                  }),
                });
                onReportCreated(placeholder);
              } catch {}
            }
          }
        }
      } catch (err: any) {
        if (err.message?.includes('existiert')) {
          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === activeRepeaterId);
          if (existing) {
            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
              method: 'PATCH',
              body: JSON.stringify({ ...parsed, notes: notes || null }),
            });
            onReportUpdated(updated);
          }
        }
      }
    }

    setCallsign('');
    setSelectedOperator(null);
    setRapport('');
    setNotes('');
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setCallsign(report.callsign);
    setSelectedOperator({ id: report.operator_id, callsign: report.callsign });
    const rapportStr = report.readability && report.strength
      ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}`
      : '';
    setRapport(rapportStr);
    setNotes(report.notes || '');
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  return (
    <div className="space-y-3">
      {/* Repeater tabs grouped by Bundesland */}
      <div className="space-y-1">
        {sortedBlCodes.map(blCode => {
          const blReps = repeatersByBl[blCode];
          const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
          return (
            <div key={blCode}>
              <div className="px-1 mb-0.5">
                <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
              </div>
              <div className="flex flex-wrap gap-1 mb-1">
                {blReps.map(r => {
                  const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                  return (
                    <button
                      key={r.repeater_id}
                      onClick={() => setActiveRepeaterId(r.repeater_id)}
                      className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#1a365d] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
                    >
                      {r.short_name}
                      {r.operator_callsign && (
                        <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
                          {r.operator_callsign}
                        </span>
                      )}
                      {repReportCount > 0 && (
                        <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
                          {repReportCount}
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}

        {simplexRepeaters.length > 0 && (
          <div>
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">Simplex</div>
            <div className="flex flex-wrap gap-1 mb-1">
              {simplexRepeaters.map(r => {
                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                return (
                  <button
                    key={r.repeater_id}
                    onClick={() => setActiveRepeaterId(r.repeater_id)}
                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#1a365d] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
                  >
                    {r.short_name}
                    {r.operator_callsign && (
                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
                        {r.operator_callsign}
                      </span>
                    )}
                    {repReportCount > 0 && (
                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
                        {repReportCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {linkedRepeaters.length > 0 && (
          <div>
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">OE-Link</div>
            <div className="flex flex-wrap gap-1 mb-1">
              {linkedRepeaters.map(r => {
                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                return (
                  <button
                    key={`oelink-${r.repeater_id}`}
                    onClick={() => setActiveRepeaterId(r.repeater_id)}
                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-blue-700 text-white font-medium' : 'bg-blue-50 text-blue-800 hover:bg-blue-100 border border-blue-200'}`}
                  >
                    {r.short_name}
                    {r.operator_callsign && (
                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-100 text-blue-700'}`}>
                        {r.operator_callsign}
                      </span>
                    )}
                    {repReportCount > 0 && (
                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-200'}`}>
                        {repReportCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Repeater info */}
      {activeRepeater && (
        <div className="text-xs text-gray-500 flex gap-4">
          {activeRepeater.frequency_mhz && <span>{activeRepeater.frequency_mhz} MHz</span>}
          {activeRepeater.offset_mhz && <span>Offset: {activeRepeater.offset_mhz > 0 ? '+' : ''}{activeRepeater.offset_mhz} MHz</span>}
          {activeRepeater.ctcss_hz && <span>CTCSS: {activeRepeater.ctcss_hz} Hz</span>}
          {activeRepeater.burst_hz && <span>Burst: {activeRepeater.burst_hz} Hz</span>}
          {activeRepeater.repeater_callsign && <span className="font-mono">{activeRepeater.repeater_callsign}</span>}
        </div>
      )}

      {/* Entry form */}
      <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow-sm p-3 flex items-center gap-2 flex-wrap">
        <CallsignInput
          value={callsign}
          onChange={setCallsign}
          onSelect={setSelectedOperator}
          autoFocus
          className="w-36"
        />
        <input
          type="text"
          value={rapport}
          onChange={e => setRapport(e.target.value.toUpperCase())}
          placeholder="5/9+20"
          className="border border-gray-300 rounded px-2 py-1 font-mono text-sm w-24 focus:outline-none focus:ring-2 focus:ring-amber-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setRapport(`5/${e.key}`);
            }
          }}
        />
        <input
          type="text"
          value={notes}
          onChange={e => setNotes(e.target.value)}
          placeholder="Sonstiges"
          className="border border-gray-300 rounded px-2 py-1 text-sm flex-1 min-w-[100px] focus:outline-none focus:ring-2 focus:ring-amber-500"
        />
        <button type="submit" className="bg-[#1a365d] hover:bg-[#7a5230] text-white px-4 py-1 rounded text-sm font-medium">
          {editingId ? 'Speichern' : 'Eintragen'}
        </button>
        {editingId && (
          <button type="button" onClick={() => { setEditingId(null); setCallsign(''); setSelectedOperator(null); setRapport(''); setNotes(''); }} className="text-gray-500 text-sm hover:text-gray-700">
            Abbrechen
          </button>
        )}
      </form>

      {/* Reports per Umsetzer */}
      <div className="space-y-2">
        {repeaters.map(rep => {
          const repReports = reports.filter(r => r.repeater_id === rep.repeater_id && !r.is_op_marker);
          const reportCount = repReports.filter(r => r.readability).length;
          const isActive = rep.repeater_id === activeRepeaterId;

          return (
            <div key={rep.repeater_id} className="bg-white rounded-lg shadow-sm overflow-hidden">
              <div
                onClick={() => setActiveRepeaterId(rep.repeater_id)}
                className={`px-3 py-1.5 flex items-center gap-2 border-b cursor-pointer ${isActive ? 'bg-[#1a365d] text-white' : 'bg-gray-50 hover:bg-gray-100'}`}
              >
                <span className={`font-medium text-sm ${isActive ? '' : 'text-gray-800'}`}>{rep.short_name}</span>
                {rep.operator_callsign && (
                  <span className={`text-xs px-1 py-0.5 rounded ${isActive ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
                    {rep.operator_callsign}
                  </span>
                )}
                <span className={`text-xs px-1.5 py-0.5 rounded-full ${isActive ? 'bg-white/20' : 'bg-[#0d6efd] text-white'}`}>{reportCount}</span>
                {rep.frequency_mhz && (
                  <span className={`text-xs ${isActive ? 'text-white/70' : 'text-gray-400'}`}>{rep.frequency_mhz} MHz</span>
                )}
              </div>
              {repReports.length > 0 && (
                <table className="w-full text-sm">
                  <tbody className="divide-y divide-gray-100">
                    {repReports.map((r, idx) => (
                      <tr
                        key={r.id}
                        onClick={() => { setActiveRepeaterId(rep.repeater_id); handleEdit(r); }}
                        className="hover:bg-amber-50 cursor-pointer"
                      >
                        <td className="px-3 py-1 text-xs text-gray-400 w-8">{idx + 1}</td>
                        <td className="px-3 py-1">
                          <span className="font-mono font-medium text-xs">{r.callsign}</span>
                          {r.bezirk_code && (
                            <span className="ml-1 text-xs bg-gray-200 rounded px-1">{r.bezirk_code}</span>
                          )}
                        </td>
                        <td className="px-3 py-1 font-mono text-xs w-24">
                          {r.readability && r.strength
                            ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}`
                            : <span className="text-gray-300">—</span>
                          }
                        </td>
                        <td className="px-3 py-1 text-xs text-gray-600">{r.notes || ''}</td>
                        <td className="px-3 py-1 w-8">
                          <button
                            onClick={e => { e.stopPropagation(); handleDelete(r.id); }}
                            className="text-red-400 hover:text-red-600 text-xs"
                          >
                            x
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import CallsignInput from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
}

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    if (!repeaterId) return;
    const operator = await getOrCreateOperator(form.callsign, form.operator);
    if (!operator) return;

    const parsed = parseRapport(form.rapport);

    try {
      const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
        method: 'POST',
        body: JSON.stringify({
          operator_id: operator.id,
          repeater_id: repeaterId,
          ...parsed,
          notes: form.notes || null,
        }),
      });
      onReportCreated(report);
    } catch (err: any) {
      if (err.message?.includes('existiert')) {
        const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
        if (existing) {
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null }),
          });
          onReportUpdated(updated);
        }
      }
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null }),
      });
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        const blReports = reports.filter(r => r.bundesland_code === bl.code);
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="bg-gray-50 px-3 py-2 flex items-center justify-between border-b">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-sm">{bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
                <label className="text-xs text-gray-500">OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufzeichen"
                  className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-24 focus:outline-none focus:ring-1 focus:ring-amber-500"
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                      />
                    );
                  })}
                </div>
                <div className="px-3 py-1.5 border-t border-gray-100">
                  {addRepBl === bl.code ? (
                    <div className="flex items-center gap-1 flex-wrap">
                      <input
                        type="text"
                        value={newRepName}
                        onChange={e => setNewRepName(e.target.value)}
                        placeholder="Name"
                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-amber-500"
                        autoFocus
                      />
                      <input
                        type="text"
                        value={newRepFreq}
                        onChange={e => setNewRepFreq(e.target.value)}
                        placeholder="MHz"
                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
                      />
                      <input
                        type="text"
                        value={newRepCallsign}
                        onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                        placeholder="Rufz."
                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
                      />
                      <button
                        onClick={() => addRepeater(bl.code)}
                        className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                      >
                        OK
                      </button>
                      <button
                        onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                        className="text-gray-400 hover:text-gray-600 text-xs"
                      >
                        Abbrechen
                      </button>
                    </div>
                  ) : (
                    <button
                      onClick={() => setAddRepBl(bl.code)}
                      className="text-xs text-gray-400 hover:text-gray-600"
                    >
                      + Umsetzer hinzufügen
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
}

function BezirkRow({ bezirk, reports, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if ((!form.operator && !form.callsign) || !repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '', notes: '' });
  };

  return (
    <div className="px-3 py-1.5">
      <div className="flex items-center gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code}
        </span>
        <span className="text-xs text-gray-500">{bezirk.name}</span>
      </div>

      <div className="flex flex-wrap gap-1 mb-1">
        {reports.map(r => (
          <div key={r.id} className="group">
            {editingId === r.id ? (
              <div className="flex items-center gap-1 bg-amber-50 rounded p-1">
                <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" />
                <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
              </div>
            ) : (
              <span
                onClick={() => onEdit(r)}
                className="inline-flex items-center gap-1 bg-gray-50 hover:bg-amber-50 rounded px-1.5 py-0.5 cursor-pointer text-xs"
              >
                <span className="font-mono font-medium">{r.callsign}</span>
                {r.readability && r.strength && (
                  <span className="text-gray-500">{r.readability}/{r.strength}{r.db_over_s9 || ''}</span>
                )}
                {r.notes && <span className="text-amber-600">({r.notes})</span>}
                <button
                  onClick={e => { e.stopPropagation(); onDelete(r.id); }}
                  className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100"
                >
                  x
                </button>
              </span>
            )}
          </div>
        ))}
      </div>

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs focus:outline-none focus:ring-1 focus:ring-amber-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v }))}
          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign }))}
          className="w-28"
        />
        <input
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[60px] focus:outline-none focus:ring-1 focus:ring-amber-500"
        />
        <button type="submit" className="bg-[#1a365d] hover:bg-[#7a5230] text-white px-2 py-0.5 rounded text-xs">
          +
        </button>
      </form>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

export default function LoginPage() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(username, password);
      navigate('/');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center">
      <div className="bg-white rounded-xl shadow-lg p-8 w-full max-w-sm">
        <h1 className="text-2xl font-bold text-[#1a365d] text-center mb-1">BOS-ARSA Log</h1>
        <p className="text-sm text-gray-500 text-center mb-6">Krisenkommunikationsübung</p>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Benutzername</label>
            <input
              type="text"
              value={username}
              onChange={e => setUsername(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-amber-500"
              placeholder="admin"
              required
              autoFocus
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Passwort</label>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-amber-500"
              required
            />
          </div>
          {error && <p className="text-red-600 text-sm">{error}</p>}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#1a365d] hover:bg-[#7a5230] text-white font-medium py-2 rounded-lg disabled:opacity-50"
          >
            {loading ? 'Anmelden...' : 'Anmelden'}
          </button>
        </form>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { apiFetch } from '../services/api';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement, PointElement, LineElement,
  Title, Tooltip, Legend, Filler,
} from 'chart.js';
import { Bar, Line } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const EXERCISE_TYPES = [
  'Krisenkommunikationsübung',
  'Notfunkübung',
  'Feldtag',
  'Relaisfunktest',
];

interface ExerciseSummary {
  id: string;
  name: string | null;
  date: string;
  participant_count: number;
  report_count: number;
}

function getQuarter(date: string): number {
  const month = new Date(date + 'T00:00:00').getMonth();
  return Math.floor(month / 3) + 1;
}

export default function DashboardPage() {
  const { admin } = useAuth();
  const navigate = useNavigate();
  const [exercises, setExercises] = useState<ExerciseSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [newName, setNewName] = useState(EXERCISE_TYPES[0]);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    apiFetch('/api/v1/exercises')
      .then(data => setExercises(data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const formatDate = (d: string) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-AT', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
  };

  // Compute nearest exercise to today
  const today = new Date().toISOString().split('T')[0];
  const nearestId = exercises.length > 0
    ? exercises.reduce((closest, e) => {
        const dCur = Math.abs(new Date(e.date).getTime() - new Date(today).getTime());
        const dBest = Math.abs(new Date(closest.date).getTime() - new Date(today).getTime());
        return dCur < dBest ? e : closest;
      }, exercises[0]).id
    : null;

  // Compute quarterly and yearly totals
  const quarterTotals: Record<number, { participants: number; reports: number }> = {};
  let yearParticipants = 0;
  let yearReports = 0;

  for (const ex of exercises) {
    const q = getQuarter(ex.date);
    if (!quarterTotals[q]) quarterTotals[q] = { participants: 0, reports: 0 };
    quarterTotals[q].participants += ex.participant_count;
    quarterTotals[q].reports += ex.report_count;
    yearParticipants += ex.participant_count;
    yearReports += ex.report_count;
  }

  // Build rows with quarter subtotals inserted
  const buildRows = () => {
    const rows: { type: 'exercise' | 'quarter' | 'year'; data?: ExerciseSummary; quarter?: number; participants?: number; reports?: number }[] = [];
    let lastQuarter = 0;

    for (let i = 0; i < exercises.length; i++) {
      const ex = exercises[i];
      const q = getQuarter(ex.date);
      const nextEx = exercises[i + 1];
      const nextQ = nextEx ? getQuarter(nextEx.date) : 0;

      rows.push({ type: 'exercise', data: ex });

      // Insert quarter subtotal when quarter changes or at last exercise
      if (q !== nextQ && quarterTotals[q]) {
        rows.push({ type: 'quarter', quarter: q, ...quarterTotals[q] });
        lastQuarter = q;
      }
    }

    // Yearly total
    if (exercises.length > 0) {
      rows.push({ type: 'year', participants: yearParticipants, reports: yearReports });
    }

    return rows;
  };

  const QUARTER_LABELS: Record<number, string> = { 1: 'Q1 (Jan-Mär)', 2: 'Q2 (Apr-Jun)', 3: 'Q3 (Jul-Sep)', 4: 'Q4 (Okt-Dez)' };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[#1a365d]">Gesamtübersicht</h1>
          <p className="text-sm text-gray-500">Willkommen, {admin?.username}</p>
        </div>
        {admin?.role === 'admin' && (
          <button
            onClick={() => setShowCreate(v => !v)}
            className="bg-[#1a365d] hover:bg-[#7a5230] text-white px-4 py-2 rounded-lg text-sm font-medium"
          >
            + Neue Übung
          </button>
        )}
      </div>

      {showCreate && (
        <div className="bg-white rounded-xl shadow p-4 mb-6">
          <h2 className="text-sm font-semibold text-[#1a365d] mb-3">Neue Übung anlegen</h2>
          <div className="flex items-end gap-3 flex-wrap">
            <div>
              <label className="block text-xs text-gray-500 mb-1">Datum</label>
              <input
                type="date"
                value={newDate}
                onChange={e => setNewDate(e.target.value)}
                className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
              />
            </div>
            <div className="flex-1 min-w-[200px]">
              <label className="block text-xs text-gray-500 mb-1">Typ / Name</label>
              <div className="flex gap-2">
                <select
                  value={EXERCISE_TYPES.includes(newName) ? newName : ''}
                  onChange={e => setNewName(e.target.value)}
                  className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                >
                  {EXERCISE_TYPES.map(t => (
                    <option key={t} value={t}>{t}</option>
                  ))}
                  <option value="">Eigener Name...</option>
                </select>
                {!EXERCISE_TYPES.includes(newName) && (
                  <input
                    type="text"
                    value={newName}
                    onChange={e => setNewName(e.target.value)}
                    placeholder="Name der Übung"
                    className="border border-gray-300 rounded px-2 py-1.5 text-sm flex-1 focus:outline-none focus:ring-2 focus:ring-amber-500"
                    autoFocus
                  />
                )}
              </div>
            </div>
            <button
              disabled={creating || !newDate || !newName}
              onClick={async () => {
                setCreating(true);
                try {
                  const ex = await apiFetch('/api/v1/exercises', {
                    method: 'POST',
                    body: JSON.stringify({ date: newDate, name: newName }),
                  });
                  navigate(`/exercises/${ex.id}/setup`);
                } catch {
                } finally {
                  setCreating(false);
                }
              }}
              className="bg-green-600 hover:bg-green-700 text-white px-4 py-1.5 rounded text-sm font-medium disabled:opacity-50"
            >
              {creating ? 'Erstellen...' : 'Erstellen'}
            </button>
            <button
              onClick={() => setShowCreate(false)}
              className="text-gray-500 text-sm hover:text-gray-700"
            >
              Abbrechen
            </button>
          </div>
        </div>
      )}

      {/* Summary cards */}
      {!loading && exercises.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#1a365d]">{exercises.length}</div>
            <div className="text-sm text-gray-500">Übungen</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#1a365d]">{yearParticipants}</div>
            <div className="text-sm text-gray-500">Teilnehmer gesamt</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#1a365d]">{yearReports}</div>
            <div className="text-sm text-gray-500">Rapporte gesamt</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-gray-600">
              {exercises.length > 0 ? Math.round(yearParticipants / exercises.filter(e => e.participant_count > 0).length || 1) : 0}
            </div>
            <div className="text-sm text-gray-500">Teilnehmer/Übung</div>
          </div>
        </div>
      )}

      {/* Trend chart */}
      {!loading && exercises.length > 0 && (
        <div className="bg-white rounded-xl shadow p-4 mb-6">
          <h2 className="text-sm font-semibold text-[#1a365d] mb-3">BOS-ARSA Krisenkommunikationsübungen {new Date().getFullYear()}</h2>
          <div style={{ height: 300 }}>
            <Bar
              data={{
                labels: exercises.map(e => {
                  const d = new Date(e.date + 'T00:00:00');
                  return d.toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit' });
                }),
                datasets: [
                  {
                    label: 'Teilnehmer',
                    data: exercises.map(e => e.participant_count),
                    backgroundColor: '#1a365d',
                  },
                  {
                    label: 'Rapporte',
                    data: exercises.map(e => e.report_count),
                    backgroundColor: '#d97706',
                  },
                ],
              }}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' },
                },
                scales: {
                  y: { beginAtZero: true },
                },
              }}
            />
          </div>
        </div>
      )}

      {loading ? (
        <p className="text-gray-500">Laden...</p>
      ) : exercises.length === 0 ? (
        <p className="text-gray-500">Noch keine Übungen erstellt.</p>
      ) : (
        <div className="bg-white rounded-xl shadow overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-[#1a365d] text-white">
              <tr>
                <th className="px-4 py-2 text-left">Datum</th>
                <th className="px-4 py-2 text-left">Name</th>
                <th className="px-4 py-2 text-right">Teilnehmer</th>
                <th className="px-4 py-2 text-right">Rapporte</th>
                <th className="px-4 py-2"></th>
              </tr>
            </thead>
            <tbody>
              {buildRows().map((row, idx) => {
                if (row.type === 'exercise') {
                  const ex = row.data!;
                  const isNearest = ex.id === nearestId;
                  return (
                    <tr key={ex.id} className={`border-t ${isNearest ? 'bg-amber-100 font-medium' : 'hover:bg-amber-50'}`}>
                      <td className="px-4 py-2 font-mono">
                        {formatDate(ex.date)}
                        {isNearest && <span className="ml-2 text-xs bg-amber-600 text-white px-1.5 py-0.5 rounded">Aktuell</span>}
                      </td>
                      <td className="px-4 py-2 text-gray-700">{ex.name || '—'}</td>
                      <td className="px-4 py-2 text-right">{ex.participant_count}</td>
                      <td className="px-4 py-2 text-right">{ex.report_count}</td>
                      <td className="px-4 py-2 text-right space-x-2">
                        <Link to={`/exercises/${ex.id}`} className="text-amber-700 hover:underline text-xs">
                          Öffnen
                        </Link>
                        <Link to={`/exercises/${ex.id}/reports`} className="text-blue-600 hover:underline text-xs">
                          Auswertung
                        </Link>
                      </td>
                    </tr>
                  );
                }
                if (row.type === 'quarter') {
                  return (
                    <tr key={`q${row.quarter}`} className="bg-blue-50 font-semibold border-t-2 border-blue-200">
                      <td className="px-4 py-1.5 text-blue-800 text-xs" colSpan={2}>
                        {QUARTER_LABELS[row.quarter!]}
                      </td>
                      <td className="px-4 py-1.5 text-right text-blue-800">{row.participants}</td>
                      <td className="px-4 py-1.5 text-right text-blue-800">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                if (row.type === 'year') {
                  return (
                    <tr key="year" className="bg-[#1a365d] text-white font-bold">
                      <td className="px-4 py-2" colSpan={2}>Jahresgesamt</td>
                      <td className="px-4 py-2 text-right">{row.participants}</td>
                      <td className="px-4 py-2 text-right">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                return null;
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { apiFetch } from '../services/api';

export default function OperatorsPage() {
  const [operators, setOperators] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<any>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [newOp, setNewOp] = useState({ callsign: '', name: '', qth: '', bezirk_code: '', bundesland_code: '' });
  const [page, setPage] = useState(0);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  const load = async (q?: string, offset = 0) => {
    setLoading(true);
    try {
      if (q) {
        const results = await apiFetch(`/api/v1/operators?q=${encodeURIComponent(q)}`);
        setOperators(results);
        setTotal(results.length);
      } else {
        const data = await apiFetch(`/api/v1/operators?limit=50&offset=${offset}`);
        setOperators(data.operators);
        setTotal(data.total);
      }
    } catch {} finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const handleSearch = (q: string) => {
    setSearch(q);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => load(q), 300);
  };

  const handleSave = async (op: any) => {
    try {
      const updated = await apiFetch(`/api/v1/operators/${op.id}`, {
        method: 'PATCH',
        body: JSON.stringify(op),
      });
      setOperators(prev => prev.map(o => o.id === updated.id ? updated : o));
      setEditing(null);
    } catch {}
  };

  const handleAdd = async () => {
    try {
      const created = await apiFetch('/api/v1/operators', {
        method: 'POST',
        body: JSON.stringify(newOp),
      });
      setOperators(prev => [created, ...prev]);
      setShowAdd(false);
      setNewOp({ callsign: '', name: '', qth: '', bezirk_code: '', bundesland_code: '' });
    } catch (e: any) {
      alert(e.message);
    }
  };

  const handlePage = (dir: number) => {
    const newPage = page + dir;
    setPage(newPage);
    load(undefined, newPage * 50);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-bold text-[#1a365d]">Rufzeichen-Register</h1>
        <button onClick={() => setShowAdd(true)} className="bg-[#1a365d] hover:bg-[#7a5230] text-white px-3 py-1.5 rounded text-sm">
          + Neues Rufzeichen
        </button>
      </div>

      <div className="flex items-center gap-3">
        <input
          type="text"
          value={search}
          onChange={e => handleSearch(e.target.value)}
          placeholder="Rufzeichen, Name oder QTH suchen..."
          className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
          autoFocus
        />
        <span className="text-sm text-gray-500">{total} Einträge</span>
      </div>

      {showAdd && (
        <div className="bg-white rounded-lg shadow p-4 space-y-2">
          <h3 className="font-medium text-sm">Neues Rufzeichen anlegen</h3>
          <div className="flex gap-2 flex-wrap">
            <input value={newOp.callsign} onChange={e => setNewOp(p => ({ ...p, callsign: e.target.value.toUpperCase() }))} placeholder="Rufzeichen" className="border rounded px-2 py-1 text-sm font-mono uppercase w-28" />
            <input value={newOp.name} onChange={e => setNewOp(p => ({ ...p, name: e.target.value }))} placeholder="Name" className="border rounded px-2 py-1 text-sm w-32" />
            <input value={newOp.qth} onChange={e => setNewOp(p => ({ ...p, qth: e.target.value }))} placeholder="QTH" className="border rounded px-2 py-1 text-sm w-32" />
            <input value={newOp.bezirk_code} onChange={e => setNewOp(p => ({ ...p, bezirk_code: e.target.value.toUpperCase() }))} placeholder="Bezirk" className="border rounded px-2 py-1 text-sm w-16 uppercase" />
            <input value={newOp.bundesland_code} onChange={e => setNewOp(p => ({ ...p, bundesland_code: e.target.value }))} placeholder="BL" className="border rounded px-2 py-1 text-sm w-12" />
            <button onClick={handleAdd} className="bg-green-600 text-white px-3 py-1 rounded text-sm">Anlegen</button>
            <button onClick={() => setShowAdd(false)} className="text-gray-500 text-sm">Abbrechen</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-[#1a365d] text-white">
            <tr>
              <th className="px-3 py-2 text-left">Rufzeichen</th>
              <th className="px-3 py-2 text-left">Name</th>
              <th className="px-3 py-2 text-left">QTH</th>
              <th className="px-3 py-2 text-left">Bezirk</th>
              <th className="px-3 py-2 text-left">BL</th>
              <th className="px-3 py-2 text-left">Ausstattung</th>
              <th className="px-3 py-2"></th>
            </tr>
          </thead>
          <tbody>
            {operators.map(op => (
              <tr key={op.id} className="border-t hover:bg-amber-50">
                {editing?.id === op.id ? (
                  <>
                    <td className="px-3 py-1"><input value={editing.callsign} onChange={e => setEditing({ ...editing, callsign: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-24 uppercase" /></td>
                    <td className="px-3 py-1"><input value={editing.name || ''} onChange={e => setEditing({ ...editing, name: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1"><input value={editing.qth || ''} onChange={e => setEditing({ ...editing, qth: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1"><input value={editing.bezirk_code || ''} onChange={e => setEditing({ ...editing, bezirk_code: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 text-xs w-12 uppercase" /></td>
                    <td className="px-3 py-1"><input value={editing.bundesland_code || ''} onChange={e => setEditing({ ...editing, bundesland_code: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-10" /></td>
                    <td className="px-3 py-1"><input value={editing.equipment || ''} onChange={e => setEditing({ ...editing, equipment: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1 flex gap-1">
                      <button onClick={() => handleSave(editing)} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={() => setEditing(null)} className="text-gray-400 text-xs">X</button>
                    </td>
                  </>
                ) : (
                  <>
                    <td className="px-3 py-1.5 font-mono font-medium">{op.callsign}</td>
                    <td className="px-3 py-1.5">{op.name}</td>
                    <td className="px-3 py-1.5 text-gray-500">{op.qth}</td>
                    <td className="px-3 py-1.5">
                      {op.bezirk_code && (
                        <span className="text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>
                      )}
                    </td>
                    <td className="px-3 py-1.5 text-gray-500">{op.bundesland_code}</td>
                    <td className="px-3 py-1.5 text-xs text-gray-400">{op.equipment}</td>
                    <td className="px-3 py-1.5">
                      <button onClick={() => setEditing({ ...op })} className="text-amber-700 hover:underline text-xs">
                        Bearbeiten
                      </button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {!search && (
        <div className="flex items-center justify-center gap-4">
          <button onClick={() => handlePage(-1)} disabled={page === 0} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Zurück
          </button>
          <span className="text-sm text-gray-400">Seite {page + 1}</span>
          <button onClick={() => handlePage(1)} disabled={operators.length < 50} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Weiter
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import CallsignInput from './CallsignInput';

const BUNDESLAND_NAMES: Record<string, string> = {
  '01': 'OE1 Wien',
  '02': 'OE2 Salzburg',
  '03': 'OE3 Niederösterreich',
  '04': 'OE4 Burgenland',
  '05': 'OE5 Oberösterreich',
  '06': 'OE6 Steiermark',
  '07': 'OE7 Tirol',
  '08': 'OE8 Kärnten',
  '09': 'OE9 Vorarlberg',
  '10': 'Slowenien',
};

interface Props {
  exerciseId: string;
  repeaters: any[];
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

export default function LandMode({ exerciseId, repeaters, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [activeRepeaterId, setActiveRepeaterId] = useState<number | null>(null);

  // Entry form state
  const [callsign, setCallsign] = useState('');
  const [selectedOperator, setSelectedOperator] = useState<any>(null);
  const [rapport, setRapport] = useState('');
  const [notes, setNotes] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    if (repeaters.length > 0 && !activeRepeaterId) {
      setActiveRepeaterId(repeaters[0].repeater_id);
    }
  }, [repeaters, activeRepeaterId]);

  const activeRepeater = repeaters.find(r => r.repeater_id === activeRepeaterId);
  const repeaterReports = reports.filter(r => r.repeater_id === activeRepeaterId);

  // Group repeaters by Bundesland
  const repeatersByBl: Record<string, any[]> = {};
  const simplexRepeaters: any[] = [];
  const linkedRepeaters: any[] = [];
  for (const r of repeaters) {
    if (r.type === 'simplex') {
      simplexRepeaters.push(r);
    } else {
      const blCode = r.bundesland_code || '_other';
      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
      repeatersByBl[blCode].push(r);
      if (r.is_linked) linkedRepeaters.push(r);
    }
  }

  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    if (a === '_other') return 1;
    if (b === '_other') return -1;
    return a.localeCompare(b);
  });

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!activeRepeaterId) return;
    const operator = await getOrCreateOperator(callsign, selectedOperator);
    if (!operator) return;
    setSelectedOperator(operator);

    const parsed = parseRapport(rapport);

    if (editingId) {
      try {
        const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
          method: 'PATCH',
          body: JSON.stringify({ ...parsed, notes: notes || null }),
        });
        onReportUpdated(updated);
        setEditingId(null);
      } catch {}
    } else {
      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: activeRepeaterId,
            ...parsed,
            notes: notes || null,
          }),
        });
        onReportCreated(report);

        // Cross-repeater sync: create placeholder entries on other repeaters
        for (const rep of repeaters) {
          if (rep.repeater_id !== activeRepeaterId) {
            const exists = reports.some(r => r.operator_id === operator.id && r.repeater_id === rep.repeater_id);
            if (!exists) {
              try {
                const placeholder = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
                  method: 'POST',
                  body: JSON.stringify({
                    operator_id: operator.id,
                    repeater_id: rep.repeater_id,
                  }),
                });
                onReportCreated(placeholder);
              } catch {}
            }
          }
        }
      } catch (err: any) {
        if (err.message?.includes('existiert')) {
          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === activeRepeaterId);
          if (existing) {
            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
              method: 'PATCH',
              body: JSON.stringify({ ...parsed, notes: notes || null }),
            });
            onReportUpdated(updated);
          }
        }
      }
    }

    setCallsign('');
    setSelectedOperator(null);
    setRapport('');
    setNotes('');
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setCallsign(report.callsign);
    setSelectedOperator({ id: report.operator_id, callsign: report.callsign });
    const rapportStr = report.readability && report.strength
      ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}`
      : '';
    setRapport(rapportStr);
    setNotes(report.notes || '');
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  return (
    <div className="space-y-3">
      {/* Repeater tabs grouped by Bundesland */}
      <div className="space-y-1">
        {sortedBlCodes.map(blCode => {
          const blReps = repeatersByBl[blCode];
          const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
          return (
            <div key={blCode}>
              <div className="px-1 mb-0.5">
                <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
              </div>
              <div className="flex flex-wrap gap-1 mb-1">
                {blReps.map(r => {
                  const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                  return (
                    <button
                      key={r.repeater_id}
                      onClick={() => setActiveRepeaterId(r.repeater_id)}
                      className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#1a365d] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
                    >
                      {r.short_name}
                      {r.operator_callsign && (
                        <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
                          {r.operator_callsign}
                        </span>
                      )}
                      {repReportCount > 0 && (
                        <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
                          {repReportCount}
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}

        {simplexRepeaters.length > 0 && (
          <div>
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">Simplex</div>
            <div className="flex flex-wrap gap-1 mb-1">
              {simplexRepeaters.map(r => {
                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                return (
                  <button
                    key={r.repeater_id}
                    onClick={() => setActiveRepeaterId(r.repeater_id)}
                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#1a365d] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
                  >
                    {r.short_name}
                    {r.operator_callsign && (
                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
                        {r.operator_callsign}
                      </span>
                    )}
                    {repReportCount > 0 && (
                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
                        {repReportCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {linkedRepeaters.length > 0 && (
          <div>
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">OE-Link</div>
            <div className="flex flex-wrap gap-1 mb-1">
              {linkedRepeaters.map(r => {
                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                return (
                  <button
                    key={`oelink-${r.repeater_id}`}
                    onClick={() => setActiveRepeaterId(r.repeater_id)}
                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-blue-700 text-white font-medium' : 'bg-blue-50 text-blue-800 hover:bg-blue-100 border border-blue-200'}`}
                  >
                    {r.short_name}
                    {r.operator_callsign && (
                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-100 text-blue-700'}`}>
                        {r.operator_callsign}
                      </span>
                    )}
                    {repReportCount > 0 && (
                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-200'}`}>
                        {repReportCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Repeater info */}
      {activeRepeater && (
        <div className="text-xs text-gray-500 flex gap-4">
          {activeRepeater.frequency_mhz && <span>{activeRepeater.frequency_mhz} MHz</span>}
          {activeRepeater.offset_mhz && <span>Offset: {activeRepeater.offset_mhz > 0 ? '+' : ''}{activeRepeater.offset_mhz} MHz</span>}
          {activeRepeater.ctcss_hz && <span>CTCSS: {activeRepeater.ctcss_hz} Hz</span>}
          {activeRepeater.burst_hz && <span>Burst: {activeRepeater.burst_hz} Hz</span>}
          {activeRepeater.repeater_callsign && <span className="font-mono">{activeRepeater.repeater_callsign}</span>}
        </div>
      )}

      {/* Entry form */}
      <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow-sm p-3 flex items-center gap-2 flex-wrap">
        <CallsignInput
          value={callsign}
          onChange={setCallsign}
          onSelect={setSelectedOperator}
          autoFocus
          className="w-36"
        />
        <input
          type="text"
          value={rapport}
          onChange={e => setRapport(e.target.value.toUpperCase())}
          placeholder="5/9+20"
          className="border border-gray-300 rounded px-2 py-1 font-mono text-sm w-24 focus:outline-none focus:ring-2 focus:ring-amber-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setRapport(`5/${e.key}`);
            }
          }}
        />
        <input
          type="text"
          value={notes}
          onChange={e => setNotes(e.target.value)}
          placeholder="Sonstiges"
          className="border border-gray-300 rounded px-2 py-1 text-sm flex-1 min-w-[100px] focus:outline-none focus:ring-2 focus:ring-amber-500"
        />
        <button type="submit" className="bg-[#1a365d] hover:bg-[#2a4a7f] text-white px-4 py-1 rounded text-sm font-medium">
          {editingId ? 'Speichern' : 'Eintragen'}
        </button>
        {editingId && (
          <button type="button" onClick={() => { setEditingId(null); setCallsign(''); setSelectedOperator(null); setRapport(''); setNotes(''); }} className="text-gray-500 text-sm hover:text-gray-700">
            Abbrechen
          </button>
        )}
      </form>

      {/* Reports per Umsetzer */}
      <div className="space-y-2">
        {repeaters.map(rep => {
          const repReports = reports.filter(r => r.repeater_id === rep.repeater_id && !r.is_op_marker);
          const reportCount = repReports.filter(r => r.readability).length;
          const isActive = rep.repeater_id === activeRepeaterId;

          return (
            <div key={rep.repeater_id} className="bg-white rounded-lg shadow-sm overflow-hidden">
              <div
                onClick={() => setActiveRepeaterId(rep.repeater_id)}
                className={`px-3 py-1.5 flex items-center gap-2 border-b cursor-pointer ${isActive ? 'bg-[#1a365d] text-white' : 'bg-gray-50 hover:bg-gray-100'}`}
              >
                <span className={`font-medium text-sm ${isActive ? '' : 'text-gray-800'}`}>{rep.short_name}</span>
                {rep.operator_callsign && (
                  <span className={`text-xs px-1 py-0.5 rounded ${isActive ? 'bg-white/20' : 'bg-amber-100 text-amber-800'}`}>
                    {rep.operator_callsign}
                  </span>
                )}
                <span className={`text-xs px-1.5 py-0.5 rounded-full ${isActive ? 'bg-white/20' : 'bg-[#0d6efd] text-white'}`}>{reportCount}</span>
                {rep.frequency_mhz && (
                  <span className={`text-xs ${isActive ? 'text-white/70' : 'text-gray-400'}`}>{rep.frequency_mhz} MHz</span>
                )}
              </div>
              {repReports.length > 0 && (
                <table className="w-full text-sm">
                  <tbody className="divide-y divide-gray-100">
                    {repReports.map((r, idx) => (
                      <tr
                        key={r.id}
                        onClick={() => { setActiveRepeaterId(rep.repeater_id); handleEdit(r); }}
                        className="hover:bg-amber-50 cursor-pointer"
                      >
                        <td className="px-3 py-1 text-xs text-gray-400 w-8">{idx + 1}</td>
                        <td className="px-3 py-1">
                          <span className="font-mono font-medium text-xs">{r.callsign}</span>
                          {r.bezirk_code && (
                            <span className="ml-1 text-xs bg-gray-200 rounded px-1">{r.bezirk_code}</span>
                          )}
                        </td>
                        <td className="px-3 py-1 font-mono text-xs w-24">
                          {r.readability && r.strength
                            ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}`
                            : <span className="text-gray-300">—</span>
                          }
                        </td>
                        <td className="px-3 py-1 text-xs text-gray-600">{r.notes || ''}</td>
                        <td className="px-3 py-1 w-8">
                          <button
                            onClick={e => { e.stopPropagation(); handleDelete(r.id); }}
                            className="text-red-400 hover:text-red-600 text-xs"
                          >
                            x
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import CallsignInput from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
}

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
    }).catch(() => {});
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    if (!repeaterId) return;
    const operator = await getOrCreateOperator(form.callsign, form.operator);
    if (!operator) return;

    const parsed = parseRapport(form.rapport);

    try {
      const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
        method: 'POST',
        body: JSON.stringify({
          operator_id: operator.id,
          repeater_id: repeaterId,
          ...parsed,
          notes: form.notes || null,
        }),
      });
      onReportCreated(report);
    } catch (err: any) {
      if (err.message?.includes('existiert')) {
        const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
        if (existing) {
          const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
            method: 'PATCH',
            body: JSON.stringify({ ...parsed, notes: form.notes || null }),
          });
          onReportUpdated(updated);
        }
      }
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null }),
      });
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        const blReports = reports.filter(r => r.bundesland_code === bl.code);
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="bg-gray-50 px-3 py-2 flex items-center justify-between border-b">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-sm">{bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
                <label className="text-xs text-gray-500">OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufzeichen"
                  className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-24 focus:outline-none focus:ring-1 focus:ring-amber-500"
                />
              </div>
            </div>

            {!isCollapsed && (
              <div>
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                      />
                    );
                  })}
                </div>
                <div className="px-3 py-1.5 border-t border-gray-100">
                  {addRepBl === bl.code ? (
                    <div className="flex items-center gap-1 flex-wrap">
                      <input
                        type="text"
                        value={newRepName}
                        onChange={e => setNewRepName(e.target.value)}
                        placeholder="Name"
                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-amber-500"
                        autoFocus
                      />
                      <input
                        type="text"
                        value={newRepFreq}
                        onChange={e => setNewRepFreq(e.target.value)}
                        placeholder="MHz"
                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
                      />
                      <input
                        type="text"
                        value={newRepCallsign}
                        onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                        placeholder="Rufz."
                        className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
                      />
                      <button
                        onClick={() => addRepeater(bl.code)}
                        className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                      >
                        OK
                      </button>
                      <button
                        onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                        className="text-gray-400 hover:text-gray-600 text-xs"
                      >
                        Abbrechen
                      </button>
                    </div>
                  ) : (
                    <button
                      onClick={() => setAddRepBl(bl.code)}
                      className="text-xs text-gray-400 hover:text-gray-600"
                    >
                      + Umsetzer hinzufügen
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
}

function BezirkRow({ bezirk, reports, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if ((!form.operator && !form.callsign) || !repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '', notes: '' });
  };

  return (
    <div className="px-3 py-1.5">
      <div className="flex items-center gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code}
        </span>
        <span className="text-xs text-gray-500">{bezirk.name}</span>
      </div>

      <div className="flex flex-wrap gap-1 mb-1">
        {reports.map(r => (
          <div key={r.id} className="group">
            {editingId === r.id ? (
              <div className="flex items-center gap-1 bg-amber-50 rounded p-1">
                <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" />
                <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
              </div>
            ) : (
              <span
                onClick={() => onEdit(r)}
                className="inline-flex items-center gap-1 bg-gray-50 hover:bg-amber-50 rounded px-1.5 py-0.5 cursor-pointer text-xs"
              >
                <span className="font-mono font-medium">{r.callsign}</span>
                {r.readability && r.strength && (
                  <span className="text-gray-500">{r.readability}/{r.strength}{r.db_over_s9 || ''}</span>
                )}
                {r.notes && <span className="text-amber-600">({r.notes})</span>}
                <button
                  onClick={e => { e.stopPropagation(); onDelete(r.id); }}
                  className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100"
                >
                  x
                </button>
              </span>
            )}
          </div>
        ))}
      </div>

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs focus:outline-none focus:ring-1 focus:ring-amber-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v }))}
          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign }))}
          className="w-28"
        />
        <input
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-20 focus:outline-none focus:ring-1 focus:ring-amber-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[60px] focus:outline-none focus:ring-1 focus:ring-amber-500"
        />
        <button type="submit" className="bg-[#1a365d] hover:bg-[#2a4a7f] text-white px-2 py-0.5 rounded text-xs">
          +
        </button>
      </form>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

export default function LoginPage() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(username, password);
      navigate('/');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center">
      <div className="bg-white rounded-xl shadow-lg p-8 w-full max-w-sm">
        <h1 className="text-2xl font-bold text-[#1a365d] text-center mb-1">BOS-ARSA Log</h1>
        <p className="text-sm text-gray-500 text-center mb-6">Krisenkommunikationsübung</p>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Benutzername</label>
            <input
              type="text"
              value={username}
              onChange={e => setUsername(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-amber-500"
              placeholder="admin"
              required
              autoFocus
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Passwort</label>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-amber-500"
              required
            />
          </div>
          {error && <p className="text-red-600 text-sm">{error}</p>}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#1a365d] hover:bg-[#2a4a7f] text-white font-medium py-2 rounded-lg disabled:opacity-50"
          >
            {loading ? 'Anmelden...' : 'Anmelden'}
          </button>
        </form>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../services/api';
import { getSocket } from '../services/socket';
import LandMode from '../components/LandMode';
import BundMode from '../components/BundMode';
import RunningTotals from '../components/RunningTotals';

interface Stats {
  totalParticipants: number;
  totalReports: number;
  perRepeater: { short_name: string; count: number }[];
}

export default function ExercisePage() {
  const { id } = useParams<{ id: string }>();
  const [exercise, setExercise] = useState<any>(null);
  const [mode, setMode] = useState<'land' | 'bund'>('land');
  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
  const [reports, setReports] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [opCallsign, setOpCallsign] = useState('');
  const socketRef = useRef(getSocket());

  const refreshStats = useCallback(async () => {
    if (!id) return;
    try {
      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
      setStats(s);
    } catch {}
  }, [id]);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    apiFetch(`/api/v1/exercises/${id}`)
      .then(data => {
        setExercise(data);
        setReports(data.reports || []);
        const firstOp = (data.repeaters || []).find((r: any) => r.operator_callsign);
        if (firstOp) setOpCallsign(firstOp.operator_callsign);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
    refreshStats();
  }, [id, refreshStats]);

  useEffect(() => {
    if (!id) return;
    const socket = socketRef.current;
    socket.emit('join_exercise', { exercise_id: id });

    socket.on('report_created', (data: any) => {
      setReports(prev => [data, ...prev]);
      refreshStats();
    });
    socket.on('report_updated', (data: any) => {
      setReports(prev => prev.map(r => r.id === data.id ? data : r));
      refreshStats();
    });
    socket.on('report_deleted', (data: any) => {
      setReports(prev => prev.filter(r => r.id !== data.report_id));
      refreshStats();
    });

    return () => {
      socket.emit('leave_exercise', { exercise_id: id });
      socket.off('report_created');
      socket.off('report_updated');
      socket.off('report_deleted');
    };
  }, [id, refreshStats]);

  const handleReportCreated = useCallback((report: any) => {
    setReports(prev => [report, ...prev]);
    socketRef.current.emit('report_created', { ...report, exercise_id: id! });
    refreshStats();
  }, [id, refreshStats]);

  const handleReportUpdated = useCallback((report: any) => {
    setReports(prev => prev.map(r => r.id === report.id ? report : r));
    socketRef.current.emit('report_updated', { ...report, exercise_id: id! });
    refreshStats();
  }, [id, refreshStats]);

  const handleReportDeleted = useCallback((reportId: number) => {
    setReports(prev => prev.filter(r => r.id !== reportId));
    socketRef.current.emit('report_deleted', { report_id: reportId, exercise_id: id! });
    refreshStats();
  }, [id, refreshStats]);

  const updateOpCallsign = async (val: string) => {
    const reps = exercise?.repeaters || [];
    for (const r of reps) {
      await apiFetch(`/api/v1/exercises/${id}/repeaters/${r.repeater_id}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    setExercise((prev: any) => prev ? {
      ...prev,
      repeaters: prev.repeaters?.map((r: any) => ({ ...r, operator_callsign: val || null })),
    } : null);
  };

  if (loading) return <p className="text-gray-500 p-4">Laden...</p>;
  if (!exercise) return <p className="text-red-500 p-4">Übung nicht gefunden</p>;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h1 className="text-xl font-bold text-[#1a365d]">
          {exercise.name || 'Übung'} — {new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' })}
        </h1>
        <div className="flex items-center gap-2">
          {mode === 'land' && (
            <div className="flex items-center gap-1.5">
              <label className="text-xs text-gray-500">OP:</label>
              <input
                type="text"
                value={opCallsign}
                onChange={e => setOpCallsign(e.target.value.toUpperCase())}
                onBlur={e => updateOpCallsign(e.target.value.toUpperCase())}
                placeholder="Rufzeichen"
                className="border border-gray-300 rounded px-2 py-1 text-sm font-mono uppercase w-28 focus:outline-none focus:ring-2 focus:ring-amber-500"
              />
            </div>
          )}
          <Link to={`/exercises/${id}/setup`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-1 rounded text-sm">
            Einrichten
          </Link>
          <Link to={`/exercises/${id}/reports`} className="bg-amber-100 hover:bg-amber-200 text-amber-800 px-3 py-1 rounded text-sm">
            Auswertung
          </Link>
        </div>
      </div>

      <RunningTotals stats={stats} />

      <div className="flex gap-1 bg-white rounded-lg p-1 shadow-sm w-fit">
        <button
          onClick={() => setMode('land')}
          className={`px-4 py-1.5 rounded text-sm font-medium ${mode === 'land' ? 'bg-[#1a365d] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
        >
          Land (Umsetzer)
        </button>
        <button
          onClick={() => setMode('bund')}
          className={`px-4 py-1.5 rounded text-sm font-medium ${mode === 'bund' ? 'bg-[#1a365d] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
        >
          Bund (Bundesland)
        </button>
      </div>

      {mode === 'land' ? (
        <LandMode
          exerciseId={id!}
          repeaters={exercise.repeaters || []}
          reports={reports}
          onReportCreated={handleReportCreated}
          onReportUpdated={handleReportUpdated}
          onReportDeleted={handleReportDeleted}
        />
      ) : (
        <BundMode
          exerciseId={id!}
          reports={reports}
          onReportCreated={handleReportCreated}
          onReportUpdated={handleReportUpdated}
          onReportDeleted={handleReportDeleted}
        />
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiFetch } from '../services/api';
import { useAuth } from '../hooks/useAuth';

const BUNDESLAENDER = [
  { code: '01', name: 'Wien', label: 'OE1' },
  { code: '02', name: 'Salzburg', label: 'OE2' },
  { code: '03', name: 'Niederösterreich', label: 'OE3' },
  { code: '04', name: 'Burgenland', label: 'OE4' },
  { code: '05', name: 'Oberösterreich', label: 'OE5' },
  { code: '06', name: 'Steiermark', label: 'OE6' },
  { code: '07', name: 'Tirol', label: 'OE7' },
  { code: '08', name: 'Kärnten', label: 'OE8' },
  { code: '09', name: 'Vorarlberg', label: 'OE9' },
];

export default function ExerciseSetupPage() {
  const { id } = useParams<{ id: string }>();
  const { admin } = useAuth();
  const isAdmin = admin?.role === 'admin';
  const [exercise, setExercise] = useState<any>(null);
  const [allRepeaters, setAllRepeaters] = useState<any[]>([]);
  const [activeRepeaters, setActiveRepeaters] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeBundeslaender, setActiveBundeslaender] = useState<Set<string>>(new Set());
  const [expandedBl, setExpandedBl] = useState<Set<string>>(new Set());
  const [showAddForm, setShowAddForm] = useState<string | null>(null); // bundesland_code or 'simplex'
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepOffset, setNewRepOffset] = useState('');
  const [newRepCtcss, setNewRepCtcss] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');

  useEffect(() => {
    if (!id) return;
    Promise.all([
      apiFetch(`/api/v1/exercises/${id}`),
      apiFetch('/api/v1/repeaters'),
    ]).then(([ex, reps]) => {
      setExercise(ex);
      setAllRepeaters(reps);
      setActiveRepeaters(ex.repeaters || []);
      // Determine which Bundesländer have active repeaters
      const activeBl = new Set<string>();
      for (const er of (ex.repeaters || [])) {
        const rep = reps.find((r: any) => r.id === er.repeater_id);
        if (rep?.bundesland_code) activeBl.add(rep.bundesland_code);
      }
      setActiveBundeslaender(activeBl);
      setExpandedBl(new Set(activeBl));
    }).catch(() => {}).finally(() => setLoading(false));
  }, [id]);

  const repeatersForBl = (blCode: string) =>
    allRepeaters.filter(r => r.bundesland_code === blCode && r.type !== 'simplex');

  const simplexRepeaters = allRepeaters.filter(r => r.type === 'simplex');

  const toggleBundesland = async (blCode: string) => {
    const isActive = activeBundeslaender.has(blCode);
    const newSet = new Set(activeBundeslaender);
    const newExpanded = new Set(expandedBl);

    if (isActive) {
      // Deactivate all repeaters for this Bundesland
      const blReps = repeatersForBl(blCode);
      for (const rep of blReps) {
        if (activeRepeaters.some(r => r.repeater_id === rep.id)) {
          await apiFetch(`/api/v1/exercises/${id}/repeaters/${rep.id}`, { method: 'DELETE' });
        }
      }
      newSet.delete(blCode);
      newExpanded.delete(blCode);
      setActiveRepeaters(prev => prev.filter(r => {
        const rep = allRepeaters.find(ar => ar.id === r.repeater_id);
        return rep?.bundesland_code !== blCode;
      }));
    } else {
      newSet.add(blCode);
      newExpanded.add(blCode);
    }

    setActiveBundeslaender(newSet);
    setExpandedBl(newExpanded);
  };

  const toggleRepeater = async (repeaterId: number) => {
    const isActive = activeRepeaters.some(r => r.repeater_id === repeaterId);
    if (isActive) {
      if (!isAdmin) return; // only admin can deactivate
      await apiFetch(`/api/v1/exercises/${id}/repeaters/${repeaterId}`, { method: 'DELETE' });
      setActiveRepeaters(prev => prev.filter(r => r.repeater_id !== repeaterId));
    } else {
      await apiFetch(`/api/v1/exercises/${id}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repeaterId }),
      });
      const updated = await apiFetch(`/api/v1/exercises/${id}/repeaters`);
      setActiveRepeaters(updated);
    }
  };

  const addCustomRepeater = async (bundeslandCode: string | null) => {
    if (!newRepName && !newRepFreq) return;
    const type = bundeslandCode === null ? 'simplex' : 'repeater';
    const name = newRepName || `Direkte ${newRepFreq}`;
    const rep = await apiFetch('/api/v1/repeaters', {
      method: 'POST',
      body: JSON.stringify({
        short_name: name,
        frequency_mhz: newRepFreq ? parseFloat(newRepFreq) : null,
        offset_mhz: newRepOffset ? parseFloat(newRepOffset) : null,
        ctcss_hz: newRepCtcss ? parseFloat(newRepCtcss) : null,
        callsign: newRepCallsign || null,
        band: newRepFreq ? (parseFloat(newRepFreq) > 400 ? '70cm' : parseFloat(newRepFreq) > 200 ? '23cm' : '2m') : null,
        type,
        bundesland_code: bundeslandCode,
      }),
    });
    setAllRepeaters(prev => [...prev, rep]);
    // Auto-activate it
    await apiFetch(`/api/v1/exercises/${id}/repeaters`, {
      method: 'POST',
      body: JSON.stringify({ repeater_id: rep.id }),
    });
    const updated = await apiFetch(`/api/v1/exercises/${id}/repeaters`);
    setActiveRepeaters(updated);
    setNewRepName('');
    setNewRepFreq('');
    setNewRepOffset('');
    setNewRepCtcss('');
    setNewRepCallsign('');
    setShowAddForm(null);
  };

  const toggleExpanded = (blCode: string) => {
    setExpandedBl(prev => {
      const next = new Set(prev);
      if (next.has(blCode)) next.delete(blCode);
      else next.add(blCode);
      return next;
    });
  };

  if (loading) return <p className="text-gray-500">Laden...</p>;
  if (!exercise) return <p className="text-red-500">Übung nicht gefunden</p>;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-bold text-[#1a365d]">
          Übung einrichten — {new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT')}
        </h1>
        <div className="flex gap-2">
          <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-3 py-1.5 rounded text-sm">
            Zurück
          </Link>
        </div>
      </div>

      {/* Exercise name (admin only) */}
      {isAdmin && (
        <div className="bg-white rounded-xl shadow p-4">
          <h2 className="text-lg font-semibold text-[#1a365d] mb-3">Name der Übung</h2>
          <input
            type="text"
            defaultValue={exercise.name || ''}
            placeholder="z.B. Sonntagsrunde KW 07"
            onBlur={async (e) => {
              await apiFetch(`/api/v1/exercises/${id}`, {
                method: 'PATCH',
                body: JSON.stringify({ name: e.target.value || null }),
              });
            }}
            className="border border-gray-300 rounded-lg px-3 py-2 text-sm w-full max-w-md focus:outline-none focus:ring-2 focus:ring-amber-500"
          />
        </div>
      )}

      {/* Bundesländer selection */}
      <div className="bg-white rounded-xl shadow p-4">
        <h2 className="text-lg font-semibold text-[#1a365d] mb-3">Bundesländer auswählen</h2>
        <div className="grid grid-cols-3 sm:grid-cols-5 lg:grid-cols-9 gap-2">
          {BUNDESLAENDER.map(bl => {
            const isActive = activeBundeslaender.has(bl.code);
            const repCount = repeatersForBl(bl.code).length;
            const activeCount = activeRepeaters.filter(ar => {
              const rep = allRepeaters.find(r => r.id === ar.repeater_id);
              return rep?.bundesland_code === bl.code;
            }).length;
            return (
              <button
                key={bl.code}
                onClick={() => isAdmin && toggleBundesland(bl.code)}
                disabled={!isAdmin}
                className={`flex flex-col items-center py-2 px-1 rounded-lg border-2 transition-colors text-sm ${
                  isActive
                    ? 'border-amber-500 bg-amber-50 text-[#1a365d]'
                    : 'border-gray-200 bg-gray-50 text-gray-500 hover:border-gray-300'
                } ${!isAdmin ? 'cursor-default' : ''}`}
              >
                <span className="font-bold">{bl.label}</span>
                <span className="text-xs truncate w-full text-center">{bl.name}</span>
                {isActive && <span className="text-xs mt-0.5">{activeCount}/{repCount}</span>}
              </button>
            );
          })}
        </div>
      </div>

      {/* Per-Bundesland repeater sections */}
      {BUNDESLAENDER.filter(bl => activeBundeslaender.has(bl.code)).map(bl => {
        const blRepeaters = repeatersForBl(bl.code);
        const isExpanded = expandedBl.has(bl.code);

        return (
          <div key={bl.code} className="bg-white rounded-xl shadow overflow-hidden">
            <button
              onClick={() => toggleExpanded(bl.code)}
              className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors"
            >
              <div className="flex items-center gap-2">
                <span className="font-bold text-[#1a365d]">{bl.label}</span>
                <span className="font-semibold text-[#1a365d]">{bl.name}</span>
                <span className="text-xs bg-amber-100 text-amber-800 px-2 py-0.5 rounded-full">
                  {activeRepeaters.filter(ar => {
                    const rep = allRepeaters.find(r => r.id === ar.repeater_id);
                    return rep?.bundesland_code === bl.code;
                  }).length} / {blRepeaters.length}
                </span>
              </div>
              <span className="text-gray-400">{isExpanded ? '▲' : '▼'}</span>
            </button>

            {isExpanded && (
              <div className="border-t px-4 pb-4">
                <div className="space-y-1 mt-2">
                  {blRepeaters.map(rep => {
                    const active = activeRepeaters.find(r => r.repeater_id === rep.id);
                    return (
                      <div key={rep.id} className="flex items-center gap-3 py-2 border-b border-gray-100">
                        <label className={`flex items-center gap-2 flex-1 ${!active || isAdmin ? 'cursor-pointer' : 'cursor-default'}`}>
                          <input
                            type="checkbox"
                            checked={!!active}
                            disabled={!!active && !isAdmin}
                            onChange={() => toggleRepeater(rep.id)}
                            className="w-4 h-4 accent-amber-600"
                          />
                          <span className="font-medium text-sm">{rep.short_name}</span>
                          <span className="text-xs text-gray-500">
                            {rep.frequency_mhz && `${rep.frequency_mhz} MHz`}
                            {rep.callsign && ` (${rep.callsign})`}
                          </span>
                          {rep.ctcss_hz && <span className="text-xs text-gray-400">CTCSS {rep.ctcss_hz}</span>}
                          {rep.is_linked ? <span className="text-xs bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded">oelink</span> : null}
                          {rep.is_custom ? <span className="text-xs bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded">custom</span> : null}
                        </label>
                      </div>
                    );
                  })}
                </div>

                {/* Add custom repeater button */}
                {showAddForm === bl.code ? (
                  <div className="mt-3 p-3 bg-gray-50 rounded-lg space-y-2">
                    <div className="flex gap-2 flex-wrap">
                      <input type="text" placeholder="Name" value={newRepName} onChange={e => setNewRepName(e.target.value)} className="border rounded px-2 py-1 text-sm flex-1 min-w-[120px]" />
                      <input type="text" placeholder="Frequenz MHz" value={newRepFreq} onChange={e => setNewRepFreq(e.target.value)} className="border rounded px-2 py-1 text-sm w-28" />
                      <input type="text" placeholder="Offset MHz" value={newRepOffset} onChange={e => setNewRepOffset(e.target.value)} className="border rounded px-2 py-1 text-sm w-24" />
                      <input type="text" placeholder="CTCSS Hz" value={newRepCtcss} onChange={e => setNewRepCtcss(e.target.value)} className="border rounded px-2 py-1 text-sm w-24" />
                      <input type="text" placeholder="Rufzeichen" value={newRepCallsign} onChange={e => setNewRepCallsign(e.target.value.toUpperCase())} className="border rounded px-2 py-1 text-sm font-mono uppercase w-24" />
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => addCustomRepeater(bl.code)} className="bg-amber-600 hover:bg-amber-700 text-white px-3 py-1 rounded text-sm">Hinzufügen</button>
                      <button onClick={() => setShowAddForm(null)} className="text-gray-500 text-sm hover:text-gray-700">Abbrechen</button>
                    </div>
                  </div>
                ) : (
                  <button onClick={() => setShowAddForm(bl.code)} className="mt-2 text-sm text-amber-700 hover:text-amber-900 font-medium">
                    + Umsetzer hinzufügen
                  </button>
                )}
              </div>
            )}
          </div>
        );
      })}

      {/* Simplex frequencies */}
      <div className="bg-white rounded-xl shadow overflow-hidden">
        <div className="p-4">
          <h2 className="text-lg font-semibold text-[#1a365d] mb-3">Simplex-Frequenzen</h2>
          <div className="space-y-1">
            {simplexRepeaters.map(rep => {
              const active = activeRepeaters.find(r => r.repeater_id === rep.id);
              return (
                <div key={rep.id} className="flex items-center gap-3 py-2 border-b border-gray-100">
                  <label className={`flex items-center gap-2 flex-1 ${!active || isAdmin ? 'cursor-pointer' : 'cursor-default'}`}>
                    <input
                      type="checkbox"
                      checked={!!active}
                      disabled={!!active && !isAdmin}
                      onChange={() => toggleRepeater(rep.id)}
                      className="w-4 h-4 accent-amber-600"
                    />
                    <span className="font-medium text-sm">{rep.short_name}</span>
                    <span className="text-xs text-gray-500">
                      {rep.frequency_mhz && `${rep.frequency_mhz} MHz`}
                    </span>
                    {rep.is_custom ? <span className="text-xs bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded">custom</span> : null}
                  </label>
                </div>
              );
            })}
          </div>

          {/* Add custom simplex */}
          {showAddForm === 'simplex' ? (
            <div className="mt-3 p-3 bg-gray-50 rounded-lg space-y-2">
              <div className="flex gap-2 flex-wrap">
                <input type="text" placeholder="Name (optional)" value={newRepName} onChange={e => setNewRepName(e.target.value)} className="border rounded px-2 py-1 text-sm flex-1 min-w-[120px]" />
                <input type="text" placeholder="Frequenz MHz" value={newRepFreq} onChange={e => setNewRepFreq(e.target.value)} className="border rounded px-2 py-1 text-sm w-28" />
              </div>
              <div className="flex gap-2">
                <button onClick={() => addCustomRepeater(null)} className="bg-amber-600 hover:bg-amber-700 text-white px-3 py-1 rounded text-sm">Hinzufügen</button>
                <button onClick={() => setShowAddForm(null)} className="text-gray-500 text-sm hover:text-gray-700">Abbrechen</button>
              </div>
            </div>
          ) : (
            <button onClick={() => setShowAddForm('simplex')} className="mt-2 text-sm text-amber-700 hover:text-amber-900 font-medium">
              + Simplex-Frequenz hinzufügen
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { apiFetch } from '../services/api';

export default function OperatorsPage() {
  const [operators, setOperators] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<any>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [newOp, setNewOp] = useState({ callsign: '', name: '', qth: '', bezirk_code: '', bundesland_code: '' });
  const [page, setPage] = useState(0);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  const load = async (q?: string, offset = 0) => {
    setLoading(true);
    try {
      if (q) {
        const results = await apiFetch(`/api/v1/operators?q=${encodeURIComponent(q)}`);
        setOperators(results);
        setTotal(results.length);
      } else {
        const data = await apiFetch(`/api/v1/operators?limit=50&offset=${offset}`);
        setOperators(data.operators);
        setTotal(data.total);
      }
    } catch {} finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const handleSearch = (q: string) => {
    setSearch(q);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => load(q), 300);
  };

  const handleSave = async (op: any) => {
    try {
      const updated = await apiFetch(`/api/v1/operators/${op.id}`, {
        method: 'PATCH',
        body: JSON.stringify(op),
      });
      setOperators(prev => prev.map(o => o.id === updated.id ? updated : o));
      setEditing(null);
    } catch {}
  };

  const handleAdd = async () => {
    try {
      const created = await apiFetch('/api/v1/operators', {
        method: 'POST',
        body: JSON.stringify(newOp),
      });
      setOperators(prev => [created, ...prev]);
      setShowAdd(false);
      setNewOp({ callsign: '', name: '', qth: '', bezirk_code: '', bundesland_code: '' });
    } catch (e: any) {
      alert(e.message);
    }
  };

  const handlePage = (dir: number) => {
    const newPage = page + dir;
    setPage(newPage);
    load(undefined, newPage * 50);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-bold text-[#1a365d]">Rufzeichen-Register</h1>
        <button onClick={() => setShowAdd(true)} className="bg-[#1a365d] hover:bg-[#2a4a7f] text-white px-3 py-1.5 rounded text-sm">
          + Neues Rufzeichen
        </button>
      </div>

      <div className="flex items-center gap-3">
        <input
          type="text"
          value={search}
          onChange={e => handleSearch(e.target.value)}
          placeholder="Rufzeichen, Name oder QTH suchen..."
          className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
          autoFocus
        />
        <span className="text-sm text-gray-500">{total} Einträge</span>
      </div>

      {showAdd && (
        <div className="bg-white rounded-lg shadow p-4 space-y-2">
          <h3 className="font-medium text-sm">Neues Rufzeichen anlegen</h3>
          <div className="flex gap-2 flex-wrap">
            <input value={newOp.callsign} onChange={e => setNewOp(p => ({ ...p, callsign: e.target.value.toUpperCase() }))} placeholder="Rufzeichen" className="border rounded px-2 py-1 text-sm font-mono uppercase w-28" />
            <input value={newOp.name} onChange={e => setNewOp(p => ({ ...p, name: e.target.value }))} placeholder="Name" className="border rounded px-2 py-1 text-sm w-32" />
            <input value={newOp.qth} onChange={e => setNewOp(p => ({ ...p, qth: e.target.value }))} placeholder="QTH" className="border rounded px-2 py-1 text-sm w-32" />
            <input value={newOp.bezirk_code} onChange={e => setNewOp(p => ({ ...p, bezirk_code: e.target.value.toUpperCase() }))} placeholder="Bezirk" className="border rounded px-2 py-1 text-sm w-16 uppercase" />
            <input value={newOp.bundesland_code} onChange={e => setNewOp(p => ({ ...p, bundesland_code: e.target.value }))} placeholder="BL" className="border rounded px-2 py-1 text-sm w-12" />
            <button onClick={handleAdd} className="bg-green-600 text-white px-3 py-1 rounded text-sm">Anlegen</button>
            <button onClick={() => setShowAdd(false)} className="text-gray-500 text-sm">Abbrechen</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-[#1a365d] text-white">
            <tr>
              <th className="px-3 py-2 text-left">Rufzeichen</th>
              <th className="px-3 py-2 text-left">Name</th>
              <th className="px-3 py-2 text-left">QTH</th>
              <th className="px-3 py-2 text-left">Bezirk</th>
              <th className="px-3 py-2 text-left">BL</th>
              <th className="px-3 py-2 text-left">Ausstattung</th>
              <th className="px-3 py-2"></th>
            </tr>
          </thead>
          <tbody>
            {operators.map(op => (
              <tr key={op.id} className="border-t hover:bg-amber-50">
                {editing?.id === op.id ? (
                  <>
                    <td className="px-3 py-1"><input value={editing.callsign} onChange={e => setEditing({ ...editing, callsign: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-24 uppercase" /></td>
                    <td className="px-3 py-1"><input value={editing.name || ''} onChange={e => setEditing({ ...editing, name: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1"><input value={editing.qth || ''} onChange={e => setEditing({ ...editing, qth: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1"><input value={editing.bezirk_code || ''} onChange={e => setEditing({ ...editing, bezirk_code: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 text-xs w-12 uppercase" /></td>
                    <td className="px-3 py-1"><input value={editing.bundesland_code || ''} onChange={e => setEditing({ ...editing, bundesland_code: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-10" /></td>
                    <td className="px-3 py-1"><input value={editing.equipment || ''} onChange={e => setEditing({ ...editing, equipment: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1 flex gap-1">
                      <button onClick={() => handleSave(editing)} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={() => setEditing(null)} className="text-gray-400 text-xs">X</button>
                    </td>
                  </>
                ) : (
                  <>
                    <td className="px-3 py-1.5 font-mono font-medium">{op.callsign}</td>
                    <td className="px-3 py-1.5">{op.name}</td>
                    <td className="px-3 py-1.5 text-gray-500">{op.qth}</td>
                    <td className="px-3 py-1.5">
                      {op.bezirk_code && (
                        <span className="text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>
                      )}
                    </td>
                    <td className="px-3 py-1.5 text-gray-500">{op.bundesland_code}</td>
                    <td className="px-3 py-1.5 text-xs text-gray-400">{op.equipment}</td>
                    <td className="px-3 py-1.5">
                      <button onClick={() => setEditing({ ...op })} className="text-amber-700 hover:underline text-xs">
                        Bearbeiten
                      </button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {!search && (
        <div className="flex items-center justify-center gap-4">
          <button onClick={() => handlePage(-1)} disabled={page === 0} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Zurück
          </button>
          <span className="text-sm text-gray-400">Seite {page + 1}</span>
          <button onClick={() => handlePage(1)} disabled={operators.length < 50} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Weiter
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { apiFetch } from '../services/api';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement, PointElement, LineElement,
  Title, Tooltip, Legend, Filler,
} from 'chart.js';
import { Bar, Line } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const EXERCISE_TYPES = [
  'Krisenkommunikationsübung',
  'Notfunkübung',
  'Feldtag',
  'Relaisfunktest',
];

interface ExerciseSummary {
  id: string;
  name: string | null;
  date: string;
  participant_count: number;
  report_count: number;
}

function getQuarter(date: string): number {
  const month = new Date(date + 'T00:00:00').getMonth();
  return Math.floor(month / 3) + 1;
}

export default function DashboardPage() {
  const { admin } = useAuth();
  const navigate = useNavigate();
  const [exercises, setExercises] = useState<ExerciseSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [newName, setNewName] = useState(EXERCISE_TYPES[0]);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    apiFetch('/api/v1/exercises')
      .then(data => setExercises(data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const formatDate = (d: string) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-AT', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
  };

  // Compute nearest exercise to today
  const today = new Date().toISOString().split('T')[0];
  const nearestId = exercises.length > 0
    ? exercises.reduce((closest, e) => {
        const dCur = Math.abs(new Date(e.date).getTime() - new Date(today).getTime());
        const dBest = Math.abs(new Date(closest.date).getTime() - new Date(today).getTime());
        return dCur < dBest ? e : closest;
      }, exercises[0]).id
    : null;

  // Compute quarterly and yearly totals
  const quarterTotals: Record<number, { participants: number; reports: number }> = {};
  let yearParticipants = 0;
  let yearReports = 0;

  for (const ex of exercises) {
    const q = getQuarter(ex.date);
    if (!quarterTotals[q]) quarterTotals[q] = { participants: 0, reports: 0 };
    quarterTotals[q].participants += ex.participant_count;
    quarterTotals[q].reports += ex.report_count;
    yearParticipants += ex.participant_count;
    yearReports += ex.report_count;
  }

  // Build rows with quarter subtotals inserted
  const buildRows = () => {
    const rows: { type: 'exercise' | 'quarter' | 'year'; data?: ExerciseSummary; quarter?: number; participants?: number; reports?: number }[] = [];
    let lastQuarter = 0;

    for (let i = 0; i < exercises.length; i++) {
      const ex = exercises[i];
      const q = getQuarter(ex.date);
      const nextEx = exercises[i + 1];
      const nextQ = nextEx ? getQuarter(nextEx.date) : 0;

      rows.push({ type: 'exercise', data: ex });

      // Insert quarter subtotal when quarter changes or at last exercise
      if (q !== nextQ && quarterTotals[q]) {
        rows.push({ type: 'quarter', quarter: q, ...quarterTotals[q] });
        lastQuarter = q;
      }
    }

    // Yearly total
    if (exercises.length > 0) {
      rows.push({ type: 'year', participants: yearParticipants, reports: yearReports });
    }

    return rows;
  };

  const QUARTER_LABELS: Record<number, string> = { 1: 'Q1 (Jan-Mär)', 2: 'Q2 (Apr-Jun)', 3: 'Q3 (Jul-Sep)', 4: 'Q4 (Okt-Dez)' };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[#1a365d]">Gesamtübersicht</h1>
          <p className="text-sm text-gray-500">Willkommen, {admin?.username}</p>
        </div>
        {admin?.role === 'admin' && (
          <button
            onClick={() => setShowCreate(v => !v)}
            className="bg-[#1a365d] hover:bg-[#2a4a7f] text-white px-4 py-2 rounded-lg text-sm font-medium"
          >
            + Neue Übung
          </button>
        )}
      </div>

      {showCreate && (
        <div className="bg-white rounded-xl shadow p-4 mb-6">
          <h2 className="text-sm font-semibold text-[#1a365d] mb-3">Neue Übung anlegen</h2>
          <div className="flex items-end gap-3 flex-wrap">
            <div>
              <label className="block text-xs text-gray-500 mb-1">Datum</label>
              <input
                type="date"
                value={newDate}
                onChange={e => setNewDate(e.target.value)}
                className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
              />
            </div>
            <div className="flex-1 min-w-[200px]">
              <label className="block text-xs text-gray-500 mb-1">Typ / Name</label>
              <div className="flex gap-2">
                <select
                  value={EXERCISE_TYPES.includes(newName) ? newName : ''}
                  onChange={e => setNewName(e.target.value)}
                  className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                >
                  {EXERCISE_TYPES.map(t => (
                    <option key={t} value={t}>{t}</option>
                  ))}
                  <option value="">Eigener Name...</option>
                </select>
                {!EXERCISE_TYPES.includes(newName) && (
                  <input
                    type="text"
                    value={newName}
                    onChange={e => setNewName(e.target.value)}
                    placeholder="Name der Übung"
                    className="border border-gray-300 rounded px-2 py-1.5 text-sm flex-1 focus:outline-none focus:ring-2 focus:ring-amber-500"
                    autoFocus
                  />
                )}
              </div>
            </div>
            <button
              disabled={creating || !newDate || !newName}
              onClick={async () => {
                setCreating(true);
                try {
                  const ex = await apiFetch('/api/v1/exercises', {
                    method: 'POST',
                    body: JSON.stringify({ date: newDate, name: newName }),
                  });
                  navigate(`/exercises/${ex.id}/setup`);
                } catch {
                } finally {
                  setCreating(false);
                }
              }}
              className="bg-green-600 hover:bg-green-700 text-white px-4 py-1.5 rounded text-sm font-medium disabled:opacity-50"
            >
              {creating ? 'Erstellen...' : 'Erstellen'}
            </button>
            <button
              onClick={() => setShowCreate(false)}
              className="text-gray-500 text-sm hover:text-gray-700"
            >
              Abbrechen
            </button>
          </div>
        </div>
      )}

      {/* Summary cards */}
      {!loading && exercises.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#1a365d]">{exercises.length}</div>
            <div className="text-sm text-gray-500">Übungen</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#1a365d]">{yearParticipants}</div>
            <div className="text-sm text-gray-500">Teilnehmer gesamt</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-[#1a365d]">{yearReports}</div>
            <div className="text-sm text-gray-500">Rapporte gesamt</div>
          </div>
          <div className="bg-white rounded-lg shadow-sm p-4 text-center">
            <div className="text-3xl font-bold text-gray-600">
              {exercises.length > 0 ? Math.round(yearParticipants / exercises.filter(e => e.participant_count > 0).length || 1) : 0}
            </div>
            <div className="text-sm text-gray-500">Teilnehmer/Übung</div>
          </div>
        </div>
      )}

      {/* Trend chart */}
      {!loading && exercises.length > 0 && (
        <div className="bg-white rounded-xl shadow p-4 mb-6">
          <h2 className="text-sm font-semibold text-[#1a365d] mb-3">BOS-ARSA Krisenkommunikationsübungen {new Date().getFullYear()}</h2>
          <div style={{ height: 300 }}>
            <Bar
              data={{
                labels: exercises.map(e => {
                  const d = new Date(e.date + 'T00:00:00');
                  return d.toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit' });
                }),
                datasets: [
                  {
                    label: 'Teilnehmer',
                    data: exercises.map(e => e.participant_count),
                    backgroundColor: '#1a365d',
                  },
                  {
                    label: 'Rapporte',
                    data: exercises.map(e => e.report_count),
                    backgroundColor: '#d97706',
                  },
                ],
              }}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' },
                },
                scales: {
                  y: { beginAtZero: true },
                },
              }}
            />
          </div>
        </div>
      )}

      {loading ? (
        <p className="text-gray-500">Laden...</p>
      ) : exercises.length === 0 ? (
        <p className="text-gray-500">Noch keine Übungen erstellt.</p>
      ) : (
        <div className="bg-white rounded-xl shadow overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-[#1a365d] text-white">
              <tr>
                <th className="px-4 py-2 text-left">Datum</th>
                <th className="px-4 py-2 text-left">Name</th>
                <th className="px-4 py-2 text-right">Teilnehmer</th>
                <th className="px-4 py-2 text-right">Rapporte</th>
                <th className="px-4 py-2"></th>
              </tr>
            </thead>
            <tbody>
              {buildRows().map((row, idx) => {
                if (row.type === 'exercise') {
                  const ex = row.data!;
                  const isNearest = ex.id === nearestId;
                  return (
                    <tr key={ex.id} className={`border-t ${isNearest ? 'bg-amber-100 font-medium' : 'hover:bg-amber-50'}`}>
                      <td className="px-4 py-2 font-mono">
                        {formatDate(ex.date)}
                        {isNearest && <span className="ml-2 text-xs bg-amber-600 text-white px-1.5 py-0.5 rounded">Aktuell</span>}
                      </td>
                      <td className="px-4 py-2 text-gray-700">{ex.name || '—'}</td>
                      <td className="px-4 py-2 text-right">{ex.participant_count}</td>
                      <td className="px-4 py-2 text-right">{ex.report_count}</td>
                      <td className="px-4 py-2 text-right space-x-2">
                        <Link to={`/exercises/${ex.id}`} className="text-amber-700 hover:underline text-xs">
                          Öffnen
                        </Link>
                        <Link to={`/exercises/${ex.id}/reports`} className="text-blue-600 hover:underline text-xs">
                          Auswertung
                        </Link>
                      </td>
                    </tr>
                  );
                }
                if (row.type === 'quarter') {
                  return (
                    <tr key={`q${row.quarter}`} className="bg-blue-50 font-semibold border-t-2 border-blue-200">
                      <td className="px-4 py-1.5 text-blue-800 text-xs" colSpan={2}>
                        {QUARTER_LABELS[row.quarter!]}
                      </td>
                      <td className="px-4 py-1.5 text-right text-blue-800">{row.participants}</td>
                      <td className="px-4 py-1.5 text-right text-blue-800">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                if (row.type === 'year') {
                  return (
                    <tr key="year" className="bg-[#1a365d] text-white font-bold">
                      <td className="px-4 py-2" colSpan={2}>Jahresgesamt</td>
                      <td className="px-4 py-2 text-right">{row.participants}</td>
                      <td className="px-4 py-2 text-right">{row.reports}</td>
                      <td></td>
                    </tr>
                  );
                }
                return null;
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

