            <div className="flex flex-wrap gap-3">
              <a
                href={`/api/v1/export/exercises/${id}/bund`}
                className="bg-blue-100 hover:bg-blue-200 text-blue-800 px-4 py-2 rounded text-sm font-medium"
                target="_blank"
              >
