import { Router } from 'express';
import { getDb } from '../db/database.js';

export const operatorsRouter = Router();

// Search/list operators
operatorsRouter.get('/', (req, res) => {
  const db = getDb();
  const q = req.query.q as string;
  if (q) {
    const pattern = `%${q.toUpperCase()}%`;
    const operators = db.prepare(`
      SELECT * FROM operators
      WHERE callsign LIKE ? OR UPPER(name) LIKE ? OR UPPER(qth) LIKE ?
      ORDER BY callsign LIMIT 50
    `).all(pattern, pattern, pattern);
    res.json(operators);
  } else {
    const limit = parseInt(req.query.limit as string) || 100;
    const offset = parseInt(req.query.offset as string) || 0;
    const operators = db.prepare('SELECT * FROM operators ORDER BY callsign LIMIT ? OFFSET ?').all(limit, offset);
    const total = (db.prepare('SELECT COUNT(*) as c FROM operators').get() as any).c;
    res.json({ operators, total });
  }
});

// Get single operator with history
operatorsRouter.get('/:id', (req, res) => {
  const db = getDb();
  const operator = db.prepare('SELECT * FROM operators WHERE id = ?').get(req.params.id);
  if (!operator) {
    res.status(404).json({ error: 'Operator nicht gefunden' });
    return;
  }
  const history = db.prepare(`
    SELECT e.date, e.id as exercise_id,
      GROUP_CONCAT(r.short_name || ': ' ||
        CASE WHEN sr.is_op_marker = 1 THEN 'OP'
        ELSE COALESCE(sr.readability || '/' || sr.strength || COALESCE(sr.db_over_s9, ''), '—')
        END, ' | ') as reports
    FROM signal_reports sr
    JOIN exercises e ON e.id = sr.exercise_id
    JOIN repeaters r ON r.id = sr.repeater_id
    WHERE sr.operator_id = ?
    GROUP BY e.id
    ORDER BY e.date DESC
  `).all(req.params.id);
  res.json({ ...operator, history });
});

// Quick-add operator
operatorsRouter.post('/', (req, res) => {
  const db = getDb();
  const { callsign, name, qth, bezirk_code, bundesland_code } = req.body;
  if (!callsign) {
    res.status(400).json({ error: 'Rufzeichen erforderlich' });
    return;
  }
  try {
    const result = db.prepare(`
      INSERT INTO operators (callsign, name, qth, bezirk_code, bundesland_code)
      VALUES (?, ?, ?, ?, ?)
    `).run(callsign.toUpperCase(), name || null, qth || null, bezirk_code || null, bundesland_code || null);
    const operator = db.prepare('SELECT * FROM operators WHERE id = ?').get(result.lastInsertRowid);
    res.status(201).json(operator);
  } catch (e: any) {
    if (e.message?.includes('UNIQUE')) {
      res.status(409).json({ error: 'Rufzeichen existiert bereits' });
    } else {
      throw e;
    }
  }
});

// Update operator
operatorsRouter.patch('/:id', (req, res) => {
  const db = getDb();
  const fields = ['callsign', 'name', 'qth', 'bezirk_code', 'bundesland_code', 'is_bos_arsa', 'is_arena', 'is_portable', 'is_exercise_support', 'gender', 'email', 'equipment', 'antenna', 'has_emergency_power', 'has_lighthouse_readiness', 'latitude', 'longitude'];
  const updates: string[] = [];
  const params: any[] = [];
  for (const f of fields) {
    if (req.body[f] !== undefined) {
      updates.push(`${f} = ?`);
      params.push(f === 'callsign' ? req.body[f].toUpperCase() : req.body[f]);
    }
  }
  if (updates.length === 0) {
    res.status(400).json({ error: 'Keine Änderungen' });
    return;
  }
  updates.push("updated_at = datetime('now')");
  params.push(req.params.id);
  db.prepare(`UPDATE operators SET ${updates.join(', ')} WHERE id = ?`).run(...params);
  const operator = db.prepare('SELECT * FROM operators WHERE id = ?').get(req.params.id);
  res.json(operator);
});

import { useState, useRef, useEffect } from 'react';
import { apiFetch } from '../services/api';

interface Props {
  value: string;
  onChange: (value: string) => void;
  onSelect: (operator: any) => void;
  autoFocus?: boolean;
  className?: string;
}

export default function CallsignInput({ value, onChange, onSelect, autoFocus, className }: Props) {
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIdx, setSelectedIdx] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  useEffect(() => {
    if (autoFocus && inputRef.current) inputRef.current.focus();
  }, [autoFocus]);

  const search = (q: string) => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (q.length < 1) { setSuggestions([]); setShowSuggestions(false); return; }
    debounceRef.current = setTimeout(async () => {
      try {
        const results = await apiFetch(`/api/v1/operators?q=${encodeURIComponent(q)}`);
        setSuggestions(results);
        setShowSuggestions(results.length > 0);
        setSelectedIdx(-1);
      } catch {}
    }, 150);
  };

  const handleChange = (val: string) => {
    const upper = val.toUpperCase();
    onChange(upper);
    search(upper);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIdx(prev => Math.min(prev + 1, suggestions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIdx(prev => Math.max(prev - 1, -1));
    } else if (e.key === 'Enter' && selectedIdx >= 0) {
      e.preventDefault();
      selectSuggestion(suggestions[selectedIdx]);
    } else if (e.key === 'Escape') {
      setShowSuggestions(false);
    }
    // Keyboard shortcuts
    if (e.altKey && e.key >= '1' && e.key <= '9') {
      e.preventDefault();
      onChange(value + `5/${e.key}`);
    }
    if (e.ctrlKey && e.key >= '1' && e.key <= '9') {
      e.preventDefault();
      onChange(`OE${e.key}`);
    }
  };

  const selectSuggestion = (op: any) => {
    onChange(op.callsign);
    onSelect(op);
    setShowSuggestions(false);
    setSuggestions([]);
  };

  return (
    <div className="relative">
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={e => handleChange(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
        onFocus={() => { if (suggestions.length > 0) setShowSuggestions(true); }}
        className={`border border-gray-300 rounded px-2 py-1 font-mono uppercase text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${className || 'w-32'}`}
        placeholder="Rufzeichen"
      />
      {showSuggestions && (
        <div className="absolute z-20 top-full left-0 mt-1 bg-white border rounded shadow-lg max-h-48 overflow-auto w-64">
          {suggestions.map((op, i) => (
            <div
              key={op.id}
              onMouseDown={() => selectSuggestion(op)}
              className={`px-3 py-1.5 cursor-pointer text-sm ${i === selectedIdx ? 'bg-blue-100' : 'hover:bg-gray-100'}`}
            >
              <span className="font-mono font-bold">{op.callsign}</span>
              {op.name && <span className="ml-2 text-gray-500">{op.name}</span>}
              {op.bezirk_code && <span className="ml-1 text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

