    32→  const [selectedOperator, setSelectedOperator] = useState<any>(null);
    33→  const [rapport, setRapport] = useState('');
    34→  const [notes, setNotes] = useState('');
    35→  const [editingId, setEditingId] = useState<number | null>(null);
    36→
    37→  useEffect(() => {
    38→    if (repeaters.length > 0 && !activeRepeaterId) {
    39→      setActiveRepeaterId(repeaters[0].repeater_id);
    40→    }
    41→  }, [repeaters, activeRepeaterId]);
    42→
    43→  const activeRepeater = repeaters.find(r => r.repeater_id === activeRepeaterId);
    44→  const repeaterReports = reports.filter(r => r.repeater_id === activeRepeaterId);
    45→
    46→  // Group repeaters by Bundesland
    47→  const repeatersByBl: Record<string, any[]> = {};
    48→  const simplexRepeaters: any[] = [];
    49→  const linkedRepeaters: any[] = [];
    50→  for (const r of repeaters) {
    51→    if (r.type === 'simplex') {
    52→      simplexRepeaters.push(r);
    53→    } else {
    54→      const blCode = r.bundesland_code || '_other';
    55→      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
    56→      repeatersByBl[blCode].push(r);
    57→      if (r.is_linked) linkedRepeaters.push(r);
    58→    }
    59→  }
    60→
    61→  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    62→    if (a === '_other') return 1;
    63→    if (b === '_other') return -1;
    64→    return a.localeCompare(b);
    65→  });
    66→
    67→  const parseRapport = (raw: string) => {
    68→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    69→    if (!match) return { readability: null, strength: null, db_over_s9: null };
    70→    return {
