     6→repeatersRouter.get('/', (req, res) => {
     7→  const db = getDb();
     8→  const { bundesland_code, type } = req.query;
     9→  let sql = 'SELECT r.*, bl.name as bundesland_name FROM repeaters r LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code';
    10→  const conditions: string[] = [];
    11→  const params: any[] = [];
    12→
    13→  if (bundesland_code) {
    14→    conditions.push('r.bundesland_code = ?');
    15→    params.push(bundesland_code);
    16→  }
    17→  if (type) {
    18→    conditions.push('r.type = ?');
    19→    params.push(type);
    20→  }
    21→
    22→  if (conditions.length > 0) {
    23→    sql += ' WHERE ' + conditions.join(' AND ');
    24→  }
    25→  sql += ' ORDER BY r.sort_order, r.short_name';
    26→
    27→  const repeaters = db.prepare(sql).all(...params);
    28→  res.json(repeaters);
    29→});
