    31→repeatersRouter.post('/', (req, res) => {
    32→  const db = getDb();
    33→  const { short_name, site_name, band, callsign, frequency_mhz, offset_mhz, ctcss_hz, burst_hz, type, bundesland_code } = req.body;
    34→
    35→  if (!short_name) {
    36→    res.status(400).json({ error: 'short_name erforderlich' });
    37→    return;
    38→  }
    39→
    40→  const result = db.prepare(`
    41→    INSERT INTO repeaters (short_name, site_name, band, callsign, frequency_mhz, offset_mhz, ctcss_hz, burst_hz, type, is_linked, sort_order, bundesland_code, is_custom)
    42→    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, (SELECT COALESCE(MAX(sort_order), 0) + 1 FROM repeaters), ?, 1)
    43→  `).run(
    44→    short_name,
