     4→
     5→const BUNDESLAND_NAMES: Record<string, string> = {
     6→  '01': 'OE1 Wien',
     7→  '02': 'OE2 Salzburg',
     8→  '03': 'OE3 Niederösterreich',
     9→  '04': 'OE4 Burgenland',
    10→  '05': 'OE5 Oberösterreich',
    11→  '06': 'OE6 Steiermark',
    12→  '07': 'OE7 Tirol',
    13→  '08': 'OE8 Kärnten',
    14→  '09': 'OE9 Vorarlberg',
    15→  '10': 'Slowenien',
    16→};
    17→
    18→interface Props {
    19→  exerciseId: string;
    20→  repeaters: any[];
    21→  reports: any[];
    22→  onReportCreated: (report: any) => void;
    23→  onReportUpdated: (report: any) => void;
    24→  onReportDeleted: (reportId: number) => void;
    25→}
    26→
    27→export default function LandMode({ exerciseId, repeaters, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    28→  const [activeRepeaterId, setActiveRepeaterId] = useState<number | null>(null);
    29→
    30→  // Entry form state
    31→  const [callsign, setCallsign] = useState('');
    32→  const [selectedOperator, setSelectedOperator] = useState<any>(null);
    33→  const [rapport, setRapport] = useState('');
    34→  const [notes, setNotes] = useState('');
    35→  const [editingId, setEditingId] = useState<number | null>(null);
    36→
    37→  useEffect(() => {
    38→    if (repeaters.length > 0 && !activeRepeaterId) {
    39→      setActiveRepeaterId(repeaters[0].repeater_id);
    40→    }
    41→  }, [repeaters, activeRepeaterId]);
    42→
    43→  const activeRepeater = repeaters.find(r => r.repeater_id === activeRepeaterId);
    44→  const repeaterReports = reports.filter(r => r.repeater_id === activeRepeaterId);
    45→
    46→  // Group repeaters by Bundesland
    47→  const repeatersByBl: Record<string, any[]> = {};
    48→  const simplexRepeaters: any[] = [];
    49→  const linkedRepeaters: any[] = [];
    50→  for (const r of repeaters) {
    51→    if (r.type === 'simplex') {
    52→      simplexRepeaters.push(r);
    53→    } else {
    54→      const blCode = r.bundesland_code || '_other';
    55→      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
    56→      repeatersByBl[blCode].push(r);
    57→      if (r.is_linked) linkedRepeaters.push(r);
    58→    }
    59→  }
    60→
    61→  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    62→    if (a === '_other') return 1;
    63→    if (b === '_other') return -1;
    64→    return a.localeCompare(b);
    65→  });
    66→
    67→  const parseRapport = (raw: string) => {
    68→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    69→    if (!match) return { readability: null, strength: null, db_over_s9: null };
    70→    return {
    71→      readability: parseInt(match[1]),
    72→      strength: parseInt(match[2]),
    73→      db_over_s9: match[3]?.trim() || null,
    74→    };
    75→  };
    76→
    77→  const handleSubmit = async (e: FormEvent) => {
    78→    e.preventDefault();
    79→    if (!activeRepeaterId) return;
    80→    const operator = await getOrCreateOperator(callsign, selectedOperator);
    81→    if (!operator) return;
    82→    setSelectedOperator(operator);
    83→
    84→    const parsed = parseRapport(rapport);
    85→
    86→    if (editingId) {
    87→      try {
    88→        const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
    89→          method: 'PATCH',
    90→          body: JSON.stringify({ ...parsed, notes: notes || null }),
    91→        });
    92→        onReportUpdated(updated);
    93→        setEditingId(null);
    94→      } catch {}
    95→    } else {
    96→      try {
    97→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
    98→          method: 'POST',
    99→          body: JSON.stringify({
   100→            operator_id: operator.id,
   101→            repeater_id: activeRepeaterId,
   102→            ...parsed,
   103→            notes: notes || null,
   104→          }),
   105→        });
   106→        onReportCreated(report);
   107→
   108→        // Cross-repeater sync: create placeholder entries on other repeaters
   109→        for (const rep of repeaters) {
   110→          if (rep.repeater_id !== activeRepeaterId) {
   111→            const exists = reports.some(r => r.operator_id === operator.id && r.repeater_id === rep.repeater_id);
   112→            if (!exists) {
   113→              try {
   114→                const placeholder = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   115→                  method: 'POST',
   116→                  body: JSON.stringify({
   117→                    operator_id: operator.id,
   118→                    repeater_id: rep.repeater_id,
   119→                  }),
   120→                });
   121→                onReportCreated(placeholder);
   122→              } catch {}
   123→            }
   124→          }
   125→        }
   126→      } catch (err: any) {
   127→        if (err.message?.includes('existiert')) {
   128→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === activeRepeaterId);
   129→          if (existing) {
   130→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   131→              method: 'PATCH',
   132→              body: JSON.stringify({ ...parsed, notes: notes || null }),
   133→            });
   134→            onReportUpdated(updated);
   135→          }
   136→        }
   137→      }
   138→    }
   139→
