    if (a === '_other') return 1;
    if (b === '_other') return -1;
    return a.localeCompare(b);
  });

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    alert(`Submit: cs="${callsign}" rap="${rapport}" rep=${activeRepeaterId}`);
    if (!activeRepeaterId) return;
    if (!callsign) return;
    try {
    const operator = await getOrCreateOperator(callsign, selectedOperator);
    if (!operator) { alert('Operator nicht gefunden/erstellt'); return; }
    alert(`Operator OK: ${operator.callsign} id=${operator.id}`);
    setSelectedOperator(operator);

    const parsed = parseRapport(rapport);

    if (editingId) {
      try {
        const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
          method: 'PATCH',
          body: JSON.stringify({ ...parsed, notes: notes || null }),
        });
        onReportUpdated(updated);
        setEditingId(null);
      } catch (e: any) { alert('Edit Fehler: ' + e.message); }
    } else {
      try {
        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
          method: 'POST',
          body: JSON.stringify({
            operator_id: operator.id,
            repeater_id: activeRepeaterId,
            ...parsed,
            notes: notes || null,
          }),
        });
        alert('Report erstellt: ' + report.id);
        onReportCreated(report);

        // Cross-repeater sync: create placeholder entries on other repeaters
        for (const rep of repeaters) {
          if (rep.repeater_id !== activeRepeaterId) {
            const exists = reports.some(r => r.operator_id === operator.id && r.repeater_id === rep.repeater_id);
            if (!exists) {
              try {
                const placeholder = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
                  method: 'POST',
                  body: JSON.stringify({
                    operator_id: operator.id,
                    repeater_id: rep.repeater_id,
                  }),
                });
                onReportCreated(placeholder);
              } catch {}
            }
          }
        }
      } catch (err: any) {
        if (err.message?.includes('existiert')) {
          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === activeRepeaterId);
          if (existing) {
            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
              method: 'PATCH',
              body: JSON.stringify({ ...parsed, notes: notes || null }),
            });
            alert('Report updated: ' + updated.id);
            onReportUpdated(updated);
          } else {
            alert('Existiert aber nicht in lokaler Liste');
          }
        } else {
          alert('API Fehler: ' + (err.message || 'Unbekannt'));
        }
      }
    }

    setCallsign('');
    setSelectedOperator(null);
    setRapport('5/9');
    setNotes('');
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setCallsign(report.callsign);
    setSelectedOperator({ id: report.operator_id, callsign: report.callsign });
    const rapportStr = report.readability && report.strength
      ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}`
      : '';
    setRapport(rapportStr);
    setNotes(report.notes || '');
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  return (
    <div className="space-y-3">
      {/* Repeater tabs grouped by Bundesland */}
      <div className="space-y-1">
        {sortedBlCodes.map(blCode => {
          const blReps = repeatersByBl[blCode];
          const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
          return (
            <div key={blCode}>
              <div className="px-1 mb-0.5">
                <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
              </div>
              <div className="flex flex-wrap gap-1 mb-1">
                {blReps.map(r => {
                  const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                  return (
                    <button
                      key={r.repeater_id}
                      onClick={() => setActiveRepeaterId(r.repeater_id)}
                      className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#1e3a5f] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
                    >
                      {r.short_name}
                      {r.operator_callsign && (
                        <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-100 text-blue-800'}`}>
                          {r.operator_callsign}
                        </span>
                      )}
                      {repReportCount > 0 && (
                        <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
                          {repReportCount}
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}

        {simplexRepeaters.length > 0 && (
          <div>
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">Simplex</div>
            <div className="flex flex-wrap gap-1 mb-1">
              {simplexRepeaters.map(r => {
                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                return (
                  <button
                    key={r.repeater_id}
                    onClick={() => setActiveRepeaterId(r.repeater_id)}
                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-[#1e3a5f] text-white font-medium' : 'bg-white text-gray-700 hover:bg-gray-100 border'}`}
                  >
                    {r.short_name}
                    {r.operator_callsign && (
                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-100 text-blue-800'}`}>
                        {r.operator_callsign}
                      </span>
                    )}
                    {repReportCount > 0 && (
                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-gray-200'}`}>
                        {repReportCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {linkedRepeaters.length > 0 && (
          <div>
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide px-1 mb-0.5">OE-Link</div>
            <div className="flex flex-wrap gap-1 mb-1">
              {linkedRepeaters.map(r => {
                const repReportCount = reports.filter(rp => rp.repeater_id === r.repeater_id && !rp.is_op_marker && rp.readability).length;
                return (
                  <button
                    key={`oelink-${r.repeater_id}`}
                    onClick={() => setActiveRepeaterId(r.repeater_id)}
                    className={`px-3 py-1.5 rounded text-sm flex items-center gap-1 ${r.repeater_id === activeRepeaterId ? 'bg-blue-700 text-white font-medium' : 'bg-blue-50 text-blue-800 hover:bg-blue-100 border border-blue-200'}`}
                  >
                    {r.short_name}
                    {r.operator_callsign && (
                      <span className={`text-xs px-1 py-0.5 rounded ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-100 text-blue-700'}`}>
                        {r.operator_callsign}
                      </span>
                    )}
                    {repReportCount > 0 && (
                      <span className={`text-xs rounded-full px-1.5 ${r.repeater_id === activeRepeaterId ? 'bg-white/20' : 'bg-blue-200'}`}>
                        {repReportCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Repeater info */}
      {activeRepeater && (
        <div className="text-xs text-gray-500 flex gap-4">
          {activeRepeater.frequency_mhz && <span>{activeRepeater.frequency_mhz} MHz</span>}
          {activeRepeater.offset_mhz && <span>Offset: {activeRepeater.offset_mhz > 0 ? '+' : ''}{activeRepeater.offset_mhz} MHz</span>}
          {activeRepeater.ctcss_hz && <span>CTCSS: {activeRepeater.ctcss_hz} Hz</span>}
          {activeRepeater.burst_hz && <span>Burst: {activeRepeater.burst_hz} Hz</span>}
          {activeRepeater.repeater_callsign && <span className="font-mono">{activeRepeater.repeater_callsign}</span>}
        </div>
      )}

      {/* Entry form */}
      <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow-sm p-3 flex items-center gap-2 flex-wrap">
        <CallsignInput
          ref={callsignRef}
          value={callsign}
          onChange={setCallsign}
          onSelect={setSelectedOperator}
          autoFocus
          className="w-36"
        />
        <input
          type="text"
          value={rapport}
          onChange={e => setRapport(e.target.value.toUpperCase())}
          placeholder="5/9+20"
          className="border border-gray-300 rounded px-2 py-1 font-mono text-sm w-24 focus:outline-none focus:ring-2 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setRapport(`5/${e.key}`);
            }
          }}
        />
        <input
          type="text"
          value={notes}
          onChange={e => setNotes(e.target.value)}
          placeholder="Sonstiges"
          className="border border-gray-300 rounded px-2 py-1 text-sm flex-1 min-w-[100px] focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button type="submit" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-4 py-1 rounded text-sm font-medium">
          {editingId ? 'Speichern' : 'Eintragen'}
        </button>
        {editingId && (
          <button type="button" onClick={() => { setEditingId(null); setCallsign(''); setSelectedOperator(null); setRapport(''); setNotes(''); }} className="text-gray-500 text-sm hover:text-gray-700">
            Abbrechen
          </button>
        )}
      </form>

      {/* Reports per Umsetzer */}
      <div className="space-y-2">
        {repeaters.map(rep => {
          const repReports = reports.filter(r => r.repeater_id === rep.repeater_id && !r.is_op_marker);
          const reportCount = repReports.filter(r => r.readability).length;
          const isActive = rep.repeater_id === activeRepeaterId;

          return (
            <div key={rep.repeater_id} className="bg-white rounded-lg shadow-sm overflow-hidden">
              <div
                onClick={() => setActiveRepeaterId(rep.repeater_id)}
                className={`px-3 py-1.5 flex items-center gap-2 border-b cursor-pointer ${isActive ? 'bg-[#1e3a5f] text-white' : 'bg-gray-50 hover:bg-gray-100'}`}
              >
                <span className={`font-medium text-sm ${isActive ? '' : 'text-gray-800'}`}>{rep.short_name}</span>
                {rep.operator_callsign && (
                  <span className={`text-xs px-1 py-0.5 rounded ${isActive ? 'bg-white/20' : 'bg-blue-100 text-blue-800'}`}>
                    {rep.operator_callsign}
                  </span>
                )}
                <span className={`text-xs px-1.5 py-0.5 rounded-full ${isActive ? 'bg-white/20' : 'bg-[#0d6efd] text-white'}`}>{reportCount}</span>
                {rep.frequency_mhz && (
                  <span className={`text-xs ${isActive ? 'text-white/70' : 'text-gray-400'}`}>{rep.frequency_mhz} MHz</span>
                )}
              </div>
              {repReports.length > 0 && (
                <table className="w-full text-sm">
                  <tbody className="divide-y divide-gray-100">
                    {repReports.map((r, idx) => (
                      <tr
                        key={r.id}
                        onClick={() => { setActiveRepeaterId(rep.repeater_id); handleEdit(r); }}
                        className="hover:bg-blue-50 cursor-pointer"
                      >
                        <td className="px-3 py-1 text-xs text-gray-400 w-8">{idx + 1}</td>
                        <td className="px-3 py-1">
                          <span className="font-mono font-medium text-xs">{r.callsign}</span>
                          {r.bezirk_code && (
                            <span className="ml-1 text-xs bg-gray-200 rounded px-1">{r.bezirk_code}</span>
                          )}
                        </td>
                        <td className="px-3 py-1 font-mono text-xs w-24">
                          {r.readability && r.strength
                            ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}`
                            : <span className="text-gray-300">—</span>
                          }
                        </td>
                        <td className="px-3 py-1 text-xs text-gray-600">{r.notes || ''}</td>
                        <td className="px-3 py-1 w-8">
                          <button
                            onClick={e => { e.stopPropagation(); handleDelete(r.id); }}
                            className="text-red-400 hover:text-red-600 text-xs"
                          >
                            x
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { Router } from 'express';
import { randomUUID } from 'crypto';
import { getDb } from '../db/database.js';
import { AuthRequest, requireRole } from '../middleware/auth.js';

export const exercisesRouter = Router();

// List all exercises with summary stats
exercisesRouter.get('/', (_req, res) => {
  const db = getDb();
  const exercises = db.prepare(`
    SELECT e.id, e.date, e.name, e.notes,
      (SELECT COUNT(DISTINCT operator_id) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0) as participant_count,
      (SELECT COUNT(*) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0 AND readability IS NOT NULL) as report_count
    FROM exercises e ORDER BY e.date ASC
  `).all();
  res.json(exercises);
});

// Create exercise (admin only)
exercisesRouter.post('/', requireRole('admin'), (req, res) => {
  const { date, name } = req.body;
  if (!date || !name) {
    res.status(400).json({ error: 'Datum und Name erforderlich' });
    return;
  }
  const db = getDb();
  const id = randomUUID();
  db.prepare('INSERT INTO exercises (id, date, name) VALUES (?, ?, ?)').run(id, date, name);
  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(id);
  res.status(201).json(exercise);
});

// Get full exercise with reports
exercisesRouter.get('/:id', (req, res) => {
  const db = getDb();
  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
  if (!exercise) {
    res.status(404).json({ error: 'Übung nicht gefunden' });
    return;
  }

  const repeaters = db.prepare(`
    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked,
      r.bundesland_code, bl.name as bundesland_name
    FROM exercise_repeaters er
    JOIN repeaters r ON r.id = er.repeater_id
    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
    WHERE er.exercise_id = ?
    ORDER BY r.bundesland_code, r.sort_order
  `).all(req.params.id);

  const reports = db.prepare(`
    SELECT sr.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code,
      r.short_name as repeater_name,
      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    JOIN repeaters r ON r.id = sr.repeater_id
    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
    WHERE sr.exercise_id = ?
    ORDER BY o.bundesland_code, o.bezirk_code, o.callsign
  `).all(req.params.id);

  const attendance = db.prepare(`
    SELECT ea.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code
    FROM exercise_attendance ea
    JOIN operators o ON o.id = ea.operator_id
    WHERE ea.exercise_id = ?
    ORDER BY o.callsign
  `).all(req.params.id);

  res.json({ ...exercise, repeaters, reports, attendance });
});

// Update exercise notes/name (admin only)
exercisesRouter.patch('/:id', requireRole('admin'), (req, res) => {
  const db = getDb();
  const { notes, name } = req.body;
  const updates: string[] = [];
  const params: any[] = [];
  if (notes !== undefined) { updates.push('notes = ?'); params.push(notes); }
  if (name !== undefined) { updates.push('name = ?'); params.push(name); }
  if (updates.length === 0) {
    res.status(400).json({ error: 'Keine Änderungen' });
    return;
  }
  params.push(req.params.id);
  db.prepare(`UPDATE exercises SET ${updates.join(', ')} WHERE id = ?`).run(...params);
  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
  res.json(exercise);
});

// Get exercise stats
exercisesRouter.get('/:id/stats', (req, res) => {
  const db = getDb();
  const eid = req.params.id;
  const totalParticipants = (db.prepare('SELECT COUNT(DISTINCT operator_id) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0').get(eid) as any)?.c || 0;
  const totalReports = (db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0 AND readability IS NOT NULL').get(eid) as any)?.c || 0;
  const perRepeater = db.prepare(`
    SELECT r.short_name, COUNT(*) as count
    FROM signal_reports sr
    JOIN repeaters r ON r.id = sr.repeater_id
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0 AND sr.readability IS NOT NULL
    GROUP BY sr.repeater_id
    ORDER BY r.sort_order
  `).all(eid);

  // Bezirk breakdown: participants + reports per bezirk, grouped by bundesland
  const bezirkStats = db.prepare(`
    SELECT bl.name as bundesland, bl.code as bundesland_code, bl.sort_order as bl_sort,
      bz.code as bezirk_code, bz.name as bezirk_name, bz.is_capital,
      COUNT(DISTINCT sr.operator_id) as participants,
      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    JOIN bezirke bz ON bz.code = o.bezirk_code
    JOIN bundeslaender bl ON bl.code = bz.bundesland_code
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    GROUP BY bz.code
    ORDER BY bl.sort_order, bz.code
  `).all(eid);

  // Bundesland breakdown (works even without bezirk_code, derives BL from callsign prefix)
  const blStats = db.prepare(`
    SELECT
      COALESCE(bl.name, 'OE' || SUBSTR(o.callsign, 3, 1), 'Sonstige') as bundesland,
      COALESCE(o.bundesland_code, '0' || SUBSTR(o.callsign, 3, 1)) as bundesland_code,
      COUNT(DISTINCT sr.operator_id) as participants,
      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
      OR (o.bundesland_code IS NULL AND bl.code = '0' || SUBSTR(o.callsign, 3, 1))
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    GROUP BY COALESCE(o.bundesland_code, '0' || SUBSTR(o.callsign, 3, 1))
    ORDER BY bundesland_code
  `).all(eid);

  // Participant list: all operators with their report counts
  const participants = db.prepare(`
    SELECT o.callsign, o.name, o.bezirk_code, o.bundesland_code,
      COALESCE(bl.name, bl2.name) as bundesland_name,
      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as report_count
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
    LEFT JOIN bundeslaender bl2 ON o.bundesland_code IS NULL AND bl2.code = '0' || SUBSTR(o.callsign, 3, 1)
    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
    GROUP BY sr.operator_id
    ORDER BY COALESCE(bl.sort_order, bl2.sort_order), o.bezirk_code, o.callsign
  `).all(eid);

  res.json({ totalParticipants, totalReports, perRepeater, bezirkStats, blStats, participants });
});

